window.__X_NEWS__ = {"updated_at": "2026-10-21 18:05 Asia/Shanghai", "updated_at_iso": "2026-10-21T10:05:00Z", "count": 91, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112290597440745963", "domain": "科技", "title_en": "Merz Hosts Nvidia's Huang in Berlin to Boost German AI Investments", "title_zh": "默茨在柏林会见英伟达黄仁勋，推动德国 AI 投资", "hook_en": "In Berlin, Chancellor Friedrich Merz sat down with Nvidia CEO Jensen Huang, urging Germany to lead in industrial AI by blending its engineering prowess with cutting-edge tech.", "hook_zh": "德国总理弗里德里希·默茨与英伟达 CEO 黄仁勋会面，呼吁以工程实力引领工业 AI。", "summary_en": "At the Invest in Germany Summit on October 19, Merz welcomed global investors and discussed AI regulation with Huang, who stressed that thriving industry must come before rules, with safety rooted in engineering and best practices. Nvidia announced investments in four German startups—Agile Robots, Avelios Medical, Mirelo, and Reflex Aerospace—as part of its $10 billion European commitment, and signed a deal with the government for advanced physical AI models using German industrial data. Huang praised Germany's irreplaceable engineering, noting Nvidia's 1,000 local employees and nearly $1 billion invested last year, while Merz highlighted the nation's strong industrial base and market access to shape its economic future.", "summary_zh": "在 10 月 19 日“投资德国峰会”上，默茨与黄仁勋讨论 AI 监管；黄仁勋强调产业繁荣应先于规则，安全植根于工程与最佳实践。英伟达宣布投资 Agile Robots、Avelios Medical、Mirelo、Reflex Aerospace 四家德国初创，并纳入其 100 亿美元欧洲承诺，同时与德国政府就基于本土工业数据的物理 AI 模型达成合作。黄仁勋称赞德国工程不可替代，并提到英伟达在当地约有 1000 名员工、去年投资近 10 亿美元。", "body_en": "Merz Hosts Nvidia's Huang in Berlin to Boost German AI Investments.\n\nIn Berlin, Chancellor Friedrich Merz sat down with Nvidia CEO Jensen Huang, urging Germany to lead in industrial AI by blending its engineering prowess with cutting-edge tech.\n\nAt the Invest in Germany Summit on October 19, Merz welcomed global investors and discussed AI regulation with Huang, who stressed that thriving industry must come before rules, with safety rooted in engineering and best practices.\n\nNvidia announced investments in four German startups—Agile Robots, Avelios Medical, Mirelo, and Reflex Aerospace—as part of its $10 billion European commitment, and signed a deal with the government for advanced physical AI models using German industrial data. Huang praised Germany's irreplaceable engineering, noting Nvidia's 1,000 local employees and nearly $1 billion invested last year, while Merz highlighted the nation's strong industrial base and market access to shape its economic future.", "body_zh": "默茨在柏林会见英伟达黄仁勋，推动德国 AI 投资。\n\n德国总理弗里德里希·默茨与英伟达 CEO 黄仁勋会面，呼吁以工程实力引领工业 AI。\n\n在 10 月 19 日“投资德国峰会”上，默茨与黄仁勋讨论 AI 监管；黄仁勋强调产业繁荣应先于规则，安全植根于工程与最佳实践。\n\n英伟达宣布投资 Agile Robots、Avelios Medical、Mirelo、Reflex Aerospace 四家德国初创，并纳入其 100 亿美元欧洲承诺，同时与德国政府就基于本土工业数据的物理 AI 模型达成合作。黄仁勋称赞德国工程不可替代，并提到英伟达在当地约有 1000 名员工、去年投资近 10 亿美元。", "url": "https://x.com/i/trending/2112290597440745963", "category": "News", "topics": ["Technology", "Politics"], "updated_at": "2026-10-20T20:55:18.000Z"}, {"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112188369618784335", "domain": "科技", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国土安全部要求民事机构清除 DeepSeek 产品", "hook_en": "Federal agencies now face a clear directive: pull DeepSeek's Chinese AI tools from their systems to guard against data risks heading to China.", "hook_zh": "联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。", "summary_en": "The U.S. Department of Homeland Security issued an order on October 20 requiring civilian federal agencies to remove DeepSeek products from IT systems and halt future purchases under the Federal Acquisition Supply Chain Security Act. The move addresses threats like sensitive data transfers to China, potential intelligence generation on U.S. persons, and malware risks in the models. This builds on prior limits by some agencies and states, applying broadly to civilian executive branch systems while sparing defense networks. Reactions split, with supporters praising network protection and critics noting the model's open-source nature could spur local alternatives.", "summary_zh": "美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nFederal agencies now face a clear directive: pull DeepSeek's Chinese AI tools from their systems to guard against data risks heading to China.\n\nThe U.S. Department of Homeland Security issued an order on October 20 requiring civilian federal agencies to remove DeepSeek products from IT systems and halt future purchases under the Federal Acquisition Supply Chain Security Act. The move addresses threats like sensitive data transfers to China, potential intelligence generation on U.S.\n\npersons, and malware risks in the models. This builds on prior limits by some agencies and states, applying broadly to civilian executive branch systems while sparing defense networks. Reactions split, with supporters praising network protection and critics noting the model's open-source nature could spur local alternatives.", "body_zh": "美国土安全部要求民事机构清除 DeepSeek 产品。\n\n联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。\n\n美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。\n\n此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T09:26:15.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 将股份拨入公益基金", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 将股份拨入公益基金。\n\nAnthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。\n\n公益基金起步拟配置 5% 股份（待批准）；叠加此前承诺，约 20% 股份将用于非营利捐赠与就业冲击援助。\n\nAnthropic 承诺拿出 5% 股份用于公益，被视作对 AI「丰裕」承诺的回应。\n\n综合以上信息，Anthropic 将股份拨入公益基金一事持续引发关注。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 就能搞定。", "summary_en": "The feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile. Locked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "summary_zh": "用户可将聊天移入受保护区域，需 PIN、Face ID 或 Touch ID 解锁才可见；功能将覆盖免费到企业版各档套餐。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.\n\nThe feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile.\n\nLocked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 就能搞定。\n\n用户可将聊天移入受保护区域，需 PIN、Face ID 或 Touch ID 解锁才可见；功能将覆盖免费到企业版各档套餐。\n\n综合以上信息，OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天一事持续引发关注。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T08:41:04.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 对限制对华出口 AI 芯片的立场明显降温。\n\nOpenAI 曾大力推动美国严格限制先进 AI 芯片输往中国，如今却基本不再发声。\n\n去年 OpenAI 曾游说限制英伟达处理器流向有北京背景的实验室；知情人士称公司已停止相关倡议。这一转向有利于英伟达，也与其 2025 年一项重大基础设施合作相呼应。\n\n综合以上信息，OpenAI 对限制对华出口 AI 芯片的立场明显降温一事持续引发关注。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112525486228156479", "domain": "科技", "title_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks", "title_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过 OpenAI GPT-6 Sol", "hook_en": "In simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.", "hook_zh": "在模拟企业网络中，DeepSeek V4.1 Flash 1017 完成的多步进攻性网络安全目标多于受限版 OpenAI GPT-6 Sol。这款来自中国的开源权重模型成本更低，即便消耗更多 token。", "summary_en": "Vals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face. It achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "summary_zh": "Vals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，具备 100 万 token 上下文，并以 MIT 许可在 Hugging Face 开放权重。它在自有评测中取得如 42.7 个目标等强成绩，可在两台 NVIDIA DGX Spark 等硬件上本地运行，有开发者称其速度构成潜在国家安全风险。MiniMax M3.1 Flash 紧随其后，在编程与视觉任务上成本更低。舆论既兴奋于可负担的前沿性能，也警惕现已公开可用的双用途网络能力。", "body_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks.\n\nIn simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.\n\nVals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face.\n\nIt achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "body_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过 OpenAI GPT-6 Sol。\n\n在模拟企业网络中，DeepSeek V4.1 Flash 1017 完成的多步进攻性网络安全目标多于受限版 OpenAI GPT-6 Sol。这款来自中国的开源权重模型成本更低，即便消耗更多 token。\n\nVals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，具备 100 万 token 上下文，并以 MIT 许可在 Hugging Face 开放权重。它在自有评测中取得如 42.7 个目标等强成绩，可在两台 NVIDIA DGX Spark 等硬件上本地运行，有开发者称其速度构成潜在国家安全风险。", "url": "https://x.com/i/trending/2112525486228156479", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T17:46:45.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.\n\nNscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112613033243721837", "domain": "科技", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI 收购 Orchestra Bio，加速药物研发", "hook_en": "Imagine AI agents spotting a failed drug batch and instantly suggesting fixes to keep treatments on track for patients.", "hook_zh": "创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。", "summary_en": "OpenAI acquired Orchestra Bio, a four-year-old startup founded by Ashoka Rajendra, to integrate its platform with Rosalind AI tools for life sciences. The deal equips biopharma teams with agents that monitor studies, track timelines, flag delays, and coordinate across partners, aiming to turn scientific discoveries into patient treatments faster. It builds on OpenAI's work with customers like Moderna and Novo Nordisk, amid a trend of AI labs entering biotech. Investors and leaders like Greg Brockman expressed excitement about accelerating the 10-15 year drug development process.", "summary_zh": "OpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nImagine AI agents spotting a failed drug batch and instantly suggesting fixes to keep treatments on track for patients.\n\nOpenAI acquired Orchestra Bio, a four-year-old startup founded by Ashoka Rajendra, to integrate its platform with Rosalind AI tools for life sciences. The deal equips biopharma teams with agents that monitor studies, track timelines, flag delays, and coordinate across partners, aiming to turn scientific discoveries into patient treatments faster.\n\nIt builds on OpenAI's work with customers like Moderna and Novo Nordisk, amid a trend of AI labs entering biotech. Investors and leaders like Greg Brockman expressed excitement about accelerating the 10-15 year drug development process.", "body_zh": "OpenAI 收购 Orchestra Bio，加速药物研发。\n\n创业四周年那天，Ashoka Rajendra 得知 OpenAI 将把团队收入麾下。\n\nOpenAI 收购 Orchestra Bio，将其生物制药协作工具与面向生物、化学的 Rosalind AI 模型结合，推动发现更快转化为疗法。\n\n综合以上信息，OpenAI 收购 Orchestra Bio，加速药物研发一事持续引发关注。", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T08:47:48.000Z"}, {"id": "2112684362596766177", "domain": "科技", "title_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots", "title_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具", "hook_en": "Imagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.", "hook_zh": "一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。", "summary_en": "Viggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video. Dream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "summary_zh": "Viggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。Dream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "body_en": "Viggle JST-2 and Dream Labs Dream-1 Launch Fast AI Tools for 3D and Robots.\n\nImagine generating a full 3D world in one second for under a penny, or powering robots you've never seen before at just $3 an hour. Two new AI models make these feats real this week.\n\nViggle released JST-2, the first full-stack physics-native world foundation model that builds 3D scenes from scratch in about one second for less than a cent, allowing real-time expansion from any angle with characters and motion from text or video.\n\nDream Labs debuted Dream-1 from stealth, a robot foundation model backed by a $90 million seed round, which controls unfamiliar bimanual robots on new tasks via a public API starting at $3 per hour. Early testers praised quick successes like playground tasks on rover arms, though finer precision needs work, pointing to lower barriers for creators in simulations, games, and robotics.", "body_zh": "Viggle JST-2 与 Dream Labs Dream-1 推出快速 3D 与机器人 AI 工具。\n\n一秒生成完整三维世界、成本不到一美分，或是用每小时约 3 美元驱动从未见过的机器人——两款新模型本周让这些场景成真。\n\nViggle 发布 JST-2，号称首个全栈、物理原生的世界基础模型，可在约一秒内从零构建三维场景，成本不足一美分，并能从任意角度实时扩展，用文本或视频加入角色与动作。\n\nDream Labs 则从隐身状态亮相 Dream-1，这是一款机器人基础模型，获 9000 万美元种子轮支持，可通过公开 API 以每小时约 3 美元起控制陌生双臂机器人完成新任务。早期测试者称在漫游车机械臂上能较快完成场地任务，但精细精度仍待提升，整体降低了仿真、游戏与机器人创作者的门槛。", "url": "https://x.com/i/trending/2112684362596766177", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T23:23:26.000Z"}, {"id": "2112339042494742975", "domain": "科技", "title_en": "ChatGPT Slides Gains Real-Time Team Collaboration", "title_zh": "ChatGPT 幻灯片上线实时团队协作", "hook_en": "Imagine teams and AI agents editing the same presentation slide by slide, with comments flying in real time. OpenAI just made that a reality inside ChatGPT.", "hook_zh": "团队与 AI 智能体可逐页共编同一演示文稿，评论实时飞来飞去——OpenAI 已把这场景带进 ChatGPT。", "summary_en": "OpenAI launched real-time collaboration for ChatGPT Slides, allowing Pro, Business, and Enterprise users to share decks, edit together, leave comments, and let ChatGPT apply feedback instantly. Features include direct tweaks to text, charts, images, and shapes, starting from conversations or files, with exports to PowerPoint or Google Slides. OpenAI's Platon Mazarakis shared pride in building a multiplayer editor from the start, while users like Emily Dahin called multi-human-agent work magical for future coworking. The rollout began around October 16, 2026, positioning ChatGPT as a strong rival to tools like Canva and Figma.", "summary_zh": "OpenAI 为 ChatGPT Slides 推出实时协作，Pro、Business 与 Enterprise 用户可共享幻灯片、共同编辑、留言评论，并由 ChatGPT 即时落实反馈。功能涵盖文字、图表、图片与形状的直接调整，可从对话或文件起步，并导出到 PowerPoint 或 Google 幻灯片。OpenAI 的 Platon Mazarakis 称从一开始就按多人编辑器设计；用户 Emily Dahin 则把「多人与智能体」共创形容为未来协作的魔力。功能约自 2026 年 10 月 16 日起陆续开放，令 ChatGPT 更直接对标 Canva、Figma 等工具。", "body_en": "ChatGPT Slides Gains Real-Time Team Collaboration.\n\nImagine teams and AI agents editing the same presentation slide by slide, with comments flying in real time. OpenAI just made that a reality inside ChatGPT.\n\nOpenAI launched real-time collaboration for ChatGPT Slides, allowing Pro, Business, and Enterprise users to share decks, edit together, leave comments, and let ChatGPT apply feedback instantly. Features include direct tweaks to text, charts, images, and shapes, starting from conversations or files, with exports to PowerPoint or Google Slides.\n\nOpenAI's Platon Mazarakis shared pride in building a multiplayer editor from the start, while users like Emily Dahin called multi-human-agent work magical for future coworking. The rollout began around October 16, 2026, positioning ChatGPT as a strong rival to tools like Canva and Figma.", "body_zh": "ChatGPT 幻灯片上线实时团队协作。\n\n团队与 AI 智能体可逐页共编同一演示文稿，评论实时飞来飞去——OpenAI 已把这场景带进 ChatGPT。\n\nOpenAI 为 ChatGPT Slides 推出实时协作，Pro、Business 与 Enterprise 用户可共享幻灯片、共同编辑、留言评论，并由 ChatGPT 即时落实反馈。功能涵盖文字、图表、图片与形状的直接调整，可从对话或文件起步，并导出到 PowerPoint 或 Google 幻灯片。\n\nOpenAI 的 Platon Mazarakis 称从一开始就按多人编辑器设计；用户 Emily Dahin 则把「多人与智能体」共创形容为未来协作的魔力。功能约自 2026 年 10 月 16 日起陆续开放，令 ChatGPT 更直接对标 Canva、Figma 等工具。", "url": "https://x.com/i/trending/2112339042494742975", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T00:30:15.000Z"}, {"id": "2112741574346162483", "domain": "科技", "title_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO", "title_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO", "hook_en": "Firmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.", "hook_zh": "Firmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。", "summary_en": "Australian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million. This move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "summary_zh": "澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "body_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO.\n\nFirmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.\n\nAustralian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million.\n\nThis move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "body_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO。\n\nFirmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。\n\n澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。\n\n此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "url": "https://x.com/i/trending/2112741574346162483", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-21T04:17:50.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112044241161433358", "domain": "商业", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers.\n\nA South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "After Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478. Analysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21.\n\nNifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.\n\nAfter Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478.\n\nAnalysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:16:34.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2112507803138973871", "domain": "商业", "title_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto", "title_zh": "美联储买入约 18.27 亿美元国债，股市与加密货币上行", "hook_en": "US stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.", "hook_zh": "美联储买入约 18.27 亿美元国债并当日结算后，美股与加密货币周二走高，交易员情绪升温。", "summary_en": "The New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves. Bitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "summary_zh": "纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债，于 10 月 20 日结算，属维持银行准备金的常规二级市场买入。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称操作为「大规模」且利好风险资产。交易员关注 11 月前更多既定买入带来的流动性，但也有人指出其主要是替换到期持仓，并非扩张资产负债表。", "body_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto.\n\nUS stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.\n\nThe New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves.\n\nBitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "body_zh": "美联储买入约 18.27 亿美元国债，股市与加密货币上行。\n\n美联储买入约 18.27 亿美元国债并当日结算后，美股与加密货币周二走高，交易员情绪升温。\n\n纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债，于 10 月 20 日结算，属维持银行准备金的常规二级市场买入。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称操作为「大规模」且利好风险资产。\n\n交易员关注 11 月前更多既定买入带来的流动性，但也有人指出其主要是替换到期持仓，并非扩张资产负债表。", "url": "https://x.com/i/trending/2112507803138973871", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:09:54.000Z"}, {"id": "2112795003680342391", "domain": "商业", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标普 500 前 15 大股权重创纪录达 46.7%", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "body_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share.\n\nA handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%.\n\nThe top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "标普 500 前 15 大股权重创纪录达 46.7%。\n\n少数科技巨头主导整个标普 500，仅英伟达就占指数市值约 7.5%。买宽基基金的普通投资者未必意识到自己有多依赖这些龙头。\n\n标普 500 最大的 15 只股票合计占指数总市值创纪录的 46.7%，远超 2000 年互联网泡沫顶峰时的 27.2%。英伟达以 7.5% 居首，苹果 7.1%、Alphabet 5.9%、微软 5.6%，四家合计 26.1%。\n\n前五名市值相当于后 434 家之和，引发对热门指数基金与 ETF「分散」成色的质疑。有人强调龙头现金流强劲，也有人警告一旦放缓，被动组合将承压。", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z"}, {"id": "2112319265076367697", "domain": "商业", "title_en": "Jio Platforms IPO Fully Subscribed in Record Time on Opening Day", "title_zh": "Jio Platforms IPO 开盘当日极速满额认购", "hook_en": "India's largest IPO kicked off with a bang as Jio Platforms hit full subscription in under two hours, fueled by massive institutional bids.", "hook_zh": "印度史上最大 IPO 开门红：Jio Platforms 不到两小时即满额认购，机构抢筹踊跃。", "summary_en": "Reliance Industries' Jio Platforms launched its ₹30,213 crore IPO on October 21, priced between ₹1,065 and ₹1,119 per share, surpassing past records in size and speed. Anchor investors pledged ₹8,110 crore upfront, and qualified institutional buyers oversubscribed their portion over 3x within minutes, while retail interest built steadily. The fresh issue, aimed at debt repayment and corporate needs, values the company at around $100-108 billion and runs through October 23, with listing set for October 28. Zerodha's Nithin Kamath noted Jio's role in India's digital boom, growing the investor base from 2 crore in 2016 to over 13 crore today.", "summary_zh": "信实工业旗下 Jio Platforms 于 10 月 21 日启动约 30213 亿卢比 IPO，发行价区间每份 1065–1119 卢比，规模与认购速度均刷新纪录。锚定投资者事先承诺约 8110 亿卢比，合格机构买方份额在数分钟内超额认购逾 3 倍，散户兴趣稳步上升。募集资金主要用于还债与公司用途，估值约在 1000–1080 亿美元；申购至 10 月 23 日，预计 10 月 28 日上市。Zerodha 的 Nithin Kamath 称，Jio 推动印度数字浪潮，也让投资者基数从 2016 年约 2000 万增至逾 1.3 亿。", "body_en": "Jio Platforms IPO Fully Subscribed in Record Time on Opening Day.\n\nIndia's largest IPO kicked off with a bang as Jio Platforms hit full subscription in under two hours, fueled by massive institutional bids.\n\nReliance Industries' Jio Platforms launched its ₹30,213 crore IPO on October 21, priced between ₹1,065 and ₹1,119 per share, surpassing past records in size and speed. Anchor investors pledged ₹8,110 crore upfront, and qualified institutional buyers oversubscribed their portion over 3x within minutes, while retail interest built steadily.\n\nThe fresh issue, aimed at debt repayment and corporate needs, values the company at around $100-108 billion and runs through October 23, with listing set for October 28. Zerodha's Nithin Kamath noted Jio's role in India's digital boom, growing the investor base from 2 crore in 2016 to over 13 crore today.", "body_zh": "Jio Platforms IPO 开盘当日极速满额认购。\n\n印度史上最大 IPO 开门红：Jio Platforms 不到两小时即满额认购，机构抢筹踊跃。\n\n信实工业旗下 Jio Platforms 于 10 月 21 日启动约 30213 亿卢比 IPO，发行价区间每份 1065–1119 卢比，规模与认购速度均刷新纪录。锚定投资者事先承诺约 8110 亿卢比，合格机构买方份额在数分钟内超额认购逾 3 倍，散户兴趣稳步上升。\n\n募集资金主要用于还债与公司用途，估值约在 1000–1080 亿美元；申购至 10 月 23 日，预计 10 月 28 日上市。Zerodha 的 Nithin Kamath 称，Jio 推动印度数字浪潮，也让投资者基数从 2016 年约 2000 万增至逾 1.3 亿。", "url": "https://x.com/i/trending/2112319265076367697", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:23:27.000Z"}, {"id": "2112195413214454000", "domain": "商业", "title_en": "Amazon Stock Surges 5% on Analyst Upgrade, AI Tool Launch, and Nuclear Power Plans", "title_zh": "亚马逊股价涨超 5%：分析师上调、AI 工具与核电规划齐发力", "hook_en": "Amazon's shares jumped over 5% Monday, adding $135 billion to its market value in one day. Fresh optimism around AI tools and clean energy for data centers fueled the rally.", "hook_zh": "亚马逊周一涨逾 5%，一日市值增加约 1350 亿美元；AI 工具与数据中心清洁能源预期推升乐观情绪。", "summary_en": "Morgan Stanley upgraded Amazon to a top pick with a $350 price target, citing rapid AWS growth projected at 47% in 2027 and AI opportunities in shopping agents and robotics. The company launched TorchNeuron, an open-source tool that lets PyTorch AI developers easily run code on AWS Trainium chips with minimal changes, as CEO Andy Jassy noted it cuts weeks of rework. Amazon also partnered on a 960-megawatt nuclear project in Indiana using small modular reactors to power data centers, part of a push for over 5 gigawatts by 2039. Investors eye upcoming third-quarter results amid questions on spending and competition.", "summary_zh": "摩根士丹利将亚马逊列为首选，目标价 350 美元，理由包括预计 2027 年 AWS 增速约 47%，以及购物智能体与机器人等领域的 AI 机会。公司推出开源工具 TorchNeuron，让 PyTorch 开发者几乎无需大改即可在 AWS Trainium 芯片上运行代码；CEO 安迪·贾西称可省去数周改写。亚马逊还参与印第安纳州约 960 兆瓦小型模块化反应堆核电项目，为数据中心供电，并规划到 2039 年超过 5 吉瓦。投资者正关注即将公布的三季报，焦点仍是开支力度与竞争。", "body_en": "Amazon Stock Surges 5% on Analyst Upgrade, AI Tool Launch, and Nuclear Power Plans.\n\nAmazon's shares jumped over 5% Monday, adding $135 billion to its market value in one day. Fresh optimism around AI tools and clean energy for data centers fueled the rally.\n\nMorgan Stanley upgraded Amazon to a top pick with a $350 price target, citing rapid AWS growth projected at 47% in 2027 and AI opportunities in shopping agents and robotics. The company launched TorchNeuron, an open-source tool that lets PyTorch AI developers easily run code on AWS Trainium chips with minimal changes, as CEO Andy Jassy noted it cuts weeks of rework.\n\nAmazon also partnered on a 960-megawatt nuclear project in Indiana using small modular reactors to power data centers, part of a push for over 5 gigawatts by 2039. Investors eye upcoming third-quarter results amid questions on spending and competition.", "body_zh": "亚马逊股价涨超 5%：分析师上调、AI 工具与核电规划齐发力。\n\n亚马逊周一涨逾 5%，一日市值增加约 1350 亿美元；AI 工具与数据中心清洁能源预期推升乐观情绪。\n\n摩根士丹利将亚马逊列为首选，目标价 350 美元，理由包括预计 2027 年 AWS 增速约 47%，以及购物智能体与机器人等领域的 AI 机会。公司推出开源工具 TorchNeuron，让 PyTorch 开发者几乎无需大改即可在 AWS Trainium 芯片上运行代码；CEO 安迪·贾西称可省去数周改写。\n\n亚马逊还参与印第安纳州约 960 兆瓦小型模块化反应堆核电项目，为数据中心供电，并规划到 2039 年超过 5 吉瓦。投资者正关注即将公布的三季报，焦点仍是开支力度与竞争。", "url": "https://x.com/i/trending/2112195413214454000", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T01:49:52.000Z"}, {"id": "2112213035615990082", "domain": "商业", "title_en": "NYSE and Cboe Launch Extended Options Trading Hours", "title_zh": "纽交所与 Cboe 延长期权交易时段", "hook_en": "Imagine adjusting your trades before breakfast or right after dinner. Major exchanges are now making that possible for options on top stocks like Nvidia and Apple.", "hook_zh": "早餐前或晚饭后也能调仓：主要交易所开始为英伟达、苹果等热门标的提供更长的期权交易时间。", "summary_en": "Cboe and the New York Stock Exchange began offering pre-market options trading from 7:30 a.m. to 9:25 a.m. ET and post-market sessions starting October 19, covering high-volume names like Nvidia, Apple, Amazon, and key ETFs such as SPY and IWM. These changes meet growing demand from retail and institutional investors for more flexibility in managing positions outside regular hours, with the included options representing 53% of daily U.S. volume. Traders have mixed views—some appreciate the access, while others worry about risks like lower liquidity; NYSE plans 23-hour trading by December 6.", "summary_zh": "自 10 月 19 日起，Cboe 与纽约证券交易所为英伟达、苹果、亚马逊及 SPY、IWM 等活跃 ETF 提供美东时间早盘 7:30–9:25 的期权交易，并增设盘后时段，以满足散户与机构在常规时段外管理仓位的需求；相关期权约占美国日成交量的 53%。交易者看法不一：有人欢迎更多入口，有人担心流动性偏低等风险。纽交所计划到 12 月 6 日实现约 23 小时交易。", "body_en": "NYSE and Cboe Launch Extended Options Trading Hours.\n\nImagine adjusting your trades before breakfast or right after dinner. Major exchanges are now making that possible for options on top stocks like Nvidia and Apple.\n\nCboe and the New York Stock Exchange began offering pre-market options trading from 7:30 a.m. to 9:25 a.m. ET and post-market sessions starting October 19, covering high-volume names like Nvidia, Apple, Amazon, and key ETFs such as SPY and IWM.\n\nThese changes meet growing demand from retail and institutional investors for more flexibility in managing positions outside regular hours, with the included options representing 53% of daily U.S. volume. Traders have mixed views—some appreciate the access, while others worry about risks like lower liquidity; NYSE plans 23-hour trading by December 6.", "body_zh": "纽交所与 Cboe 延长期权交易时段。\n\n早餐前或晚饭后也能调仓：主要交易所开始为英伟达、苹果等热门标的提供更长的期权交易时间。\n\n自 10 月 19 日起，Cboe 与纽约证券交易所为英伟达、苹果、亚马逊及 SPY、IWM 等活跃 ETF 提供美东时间早盘 7:30–9:25 的期权交易，并增设盘后时段，以满足散户与机构在常规时段外管理仓位的需求；相关期权约占美国日成交量的 53%。\n\n交易者看法不一：有人欢迎更多入口，有人担心流动性偏低等风险。纽交所计划到 12 月 6 日实现约 23 小时交易。", "url": "https://x.com/i/trending/2112213035615990082", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T05:34:56.000Z"}, {"id": "2112533925725610232", "domain": "商业", "title_en": "South Korean AI Firm's IPO Flop Hits U.S. Neocloud Stocks", "title_zh": "韩国 AI 公司 IPO 首日暴跌，拖累美国 neocloud 股价", "hook_en": "Elice Inc. raised $151 million in a hyped Seoul IPO, only to crash 32% on day one—the worst for a major Korean listing.", "hook_zh": "Elice Inc. 在首尔高调 IPO 募得约 1.51 亿美元，首日却跌约 32%，创韩国大型新股近年最差开局之一。", "summary_en": "The little-known South Korean AI infrastructure company saw retail demand exceed shares 400 times, yet closed at 61,500 won, well below its 90,500 won price. This triggered a selloff in U.S. neocloud stocks renting GPU power for AI, with IREN down 7%, Cipher Digital near 7%, WhiteFiber around 6%, CoreWeave about 5%, and Nebius Group roughly 5% at points. While Elice tripled revenue and turned profitable in the first half, the debut revived doubts over justifying massive data center spending amid rising borrowing costs; one investor bought the IREN dip aggressively.", "summary_zh": "这家相对冷门的韩国 AI 基础设施公司零售认购倍数高达约 400 倍，但收盘报 61500 韩元，远低于发行价 90500 韩元。消息牵动美国出租 GPU 算力的 neocloud 板块：IREN 一度跌约 7%，Cipher Digital 近 7%，WhiteFiber 约 6%，CoreWeave 约 5%，Nebius Group 约 5%。尽管 Elice 上半年营收约增两倍并扭亏为盈，首日表现仍令市场重新质疑高借贷成本下大规模数据中心支出是否划算；也有投资者趁 IREN 回调积极买入。", "body_en": "South Korean AI Firm's IPO Flop Hits U.S. Neocloud Stocks.\n\nElice Inc. raised $151 million in a hyped Seoul IPO, only to crash 32% on day one—the worst for a major Korean listing.\n\nThe little-known South Korean AI infrastructure company saw retail demand exceed shares 400 times, yet closed at 61,500 won, well below its 90,500 won price. This triggered a selloff in U.S.\n\nneocloud stocks renting GPU power for AI, with IREN down 7%, Cipher Digital near 7%, WhiteFiber around 6%, CoreWeave about 5%, and Nebius Group roughly 5% at points. While Elice tripled revenue and turned profitable in the first half, the debut revived doubts over justifying massive data center spending amid rising borrowing costs; one investor bought the IREN dip aggressively.", "body_zh": "韩国 AI 公司 IPO 首日暴跌，拖累美国 neocloud 股价。\n\nElice Inc. 在首尔高调 IPO 募得约 1.51 亿美元，首日却跌约 32%，创韩国大型新股近年最差开局之一。\n\n这家相对冷门的韩国 AI 基础设施公司零售认购倍数高达约 400 倍，但收盘报 61500 韩元，远低于发行价 90500 韩元。\n\n消息牵动美国出租 GPU 算力的 neocloud 板块：IREN 一度跌约 7%，Cipher Digital 近 7%，WhiteFiber 约 6%，CoreWeave 约 5%，Nebius Group 约 5%。尽管 Elice 上半年营收约增两倍并扭亏为盈，首日表现仍令市场重新质疑高借贷成本下大规模数据中心支出是否划算；也有投资者趁 IREN 回调积极买入。", "url": "https://x.com/i/trending/2112533925725610232", "category": "News", "topics": ["Technology", "Business & Finance"], "updated_at": "2026-10-20T16:00:58.000Z"}, {"id": "2112329486242873542", "domain": "商业", "title_en": "QQQ Hangs Near Key Support After Volatile Week", "title_zh": "QQQ 在关键支撑附近震荡，一周波动剧烈", "hook_en": "The Invesco QQQ Trust closed at $718.36 on October 19, rebounding from a drop to $709.80 earlier in the week. Traders see it clinging to a fragile support level, with some calling for blood in options trading.", "hook_zh": "Invesco QQQ 信托 10 月 19 日收于 718.36 美元，周内曾跌至 709.80 美元；交易者称其紧贴脆弱支撑，期权端亦有人喊「见血」。", "summary_en": "The ETF, tracking the Nasdaq-100, tested the 718 area as a point of control after falling from highs near $762.86. Trader RonnieV is raising 15% to 30% cash across portfolios, spotting generational buying chances in 3 to 6 months amid warning signs in $QQQ, $SPY, inflation, and rates. While some remain unimpressed and eye breakdowns, others note it held a gap and seek upside follow-through, as the Nasdaq-100 rose 1.17% to 29,529.35. The split views highlight debate on whether this is a deeper correction or a pause in QQQ's 17% year-to-date gain.", "summary_zh": "追踪纳斯达克 100 的该 ETF 自高点约 762.86 美元回落后，在 718 一带测试控制点。交易者 RonnieV 计划把组合现金比例提到 15%–30%，称未来 3 至 6 个月或出现「一代人级别」买点，并提示 QQQ、SPY、通胀与利率信号。有人看空、等待跌破，也有人指出缺口守住、期待向上跟进；纳斯达克 100 当日涨 1.17% 至 29529.35 点。分歧集中在：这是更深回调，还是年内已涨约 17% 后的休整。", "body_en": "QQQ Hangs Near Key Support After Volatile Week.\n\nThe Invesco QQQ Trust closed at $718.36 on October 19, rebounding from a drop to $709.80 earlier in the week. Traders see it clinging to a fragile support level, with some calling for blood in options trading.\n\nThe ETF, tracking the Nasdaq-100, tested the 718 area as a point of control after falling from highs near $762.86. Trader RonnieV is raising 15% to 30% cash across portfolios, spotting generational buying chances in 3 to 6 months amid warning signs in $QQQ, $SPY, inflation, and rates.\n\nWhile some remain unimpressed and eye breakdowns, others note it held a gap and seek upside follow-through, as the Nasdaq-100 rose 1.17% to 29,529.35. The split views highlight debate on whether this is a deeper correction or a pause in QQQ's 17% year-to-date gain.", "body_zh": "QQQ 在关键支撑附近震荡，一周波动剧烈。\n\nInvesco QQQ 信托 10 月 19 日收于 718.36 美元，周内曾跌至 709.80 美元；交易者称其紧贴脆弱支撑，期权端亦有人喊「见血」。\n\n追踪纳斯达克 100 的该 ETF 自高点约 762.86 美元回落后，在 718 一带测试控制点。交易者 RonnieV 计划把组合现金比例提到 15%–30%，称未来 3 至 6 个月或出现「一代人级别」买点，并提示 QQQ、SPY、通胀与利率信号。\n\n有人看空、等待跌破，也有人指出缺口守住、期待向上跟进；纳斯达克 100 当日涨 1.17% 至 29529.35 点。分歧集中在：这是更深回调，还是年内已涨约 17% 后的休整。", "url": "https://x.com/i/trending/2112329486242873542", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-19T23:51:32.000Z"}, {"id": "2112308655303327781", "domain": "商业", "title_en": "Bank Stocks Plunge Worldwide as Yields Rise, Diverging from Market Highs", "title_zh": "收益率攀升，全球银行股大跌，与指数高位背离", "hook_en": "While major stock indexes sit near record highs, banking shares are tumbling hard—down 13% from peaks and on their longest losing streak since 2008.", "hook_zh": "主要股指接近历史高位，银行股却持续下挫——自高点回落约 13%，为 2008 年来最长连跌之一。", "summary_en": "Banking stocks globally are sliding sharply, with the KBW Nasdaq Bank Index dropping 13% from its August high and U.S. giants like Bank of America off 22-24%, Goldman Sachs near 24%, and JPMorgan down 8-11%. Rising bond yields, now at 5.14-5.15% for the 10-year Treasury, are driving unrealized losses of $326.7 billion on banks' securities holdings, even as recent earnings showed customer resilience. This split from broader markets echoes past downturn signals, though some watch credit quality and say unrealized losses may not spell crisis.", "summary_zh": "全球银行股显著走弱：KBW 纳斯达克银行指数自 8 月高点跌约 13%，美国银行跌约 22%–24%，高盛近 24%，摩根大通跌约 8%–11%。十年期美债收益率升至约 5.14%–5.15%，推高银行证券未实现亏损约 3267 亿美元，尽管近期财报显示客户韧性仍在。这种与大盘的背离令人联想起过往下行信号；也有人关注信贷质量，并认为未实现亏损未必等于危机。", "body_en": "Bank Stocks Plunge Worldwide as Yields Rise, Diverging from Market Highs.\n\nWhile major stock indexes sit near record highs, banking shares are tumbling hard—down 13% from peaks and on their longest losing streak since 2008.\n\nBanking stocks globally are sliding sharply, with the KBW Nasdaq Bank Index dropping 13% from its August high and U.S. giants like Bank of America off 22-24%, Goldman Sachs near 24%, and JPMorgan down 8-11%.\n\nRising bond yields, now at 5.14-5.15% for the 10-year Treasury, are driving unrealized losses of $326.7 billion on banks' securities holdings, even as recent earnings showed customer resilience. This split from broader markets echoes past downturn signals, though some watch credit quality and say unrealized losses may not spell crisis.", "body_zh": "收益率攀升，全球银行股大跌，与指数高位背离。\n\n主要股指接近历史高位，银行股却持续下挫——自高点回落约 13%，为 2008 年来最长连跌之一。\n\n全球银行股显著走弱：KBW 纳斯达克银行指数自 8 月高点跌约 13%，美国银行跌约 22%–24%，高盛近 24%，摩根大通跌约 8%–11%。\n\n十年期美债收益率升至约 5.14%–5.15%，推高银行证券未实现亏损约 3267 亿美元，尽管近期财报显示客户韧性仍在。这种与大盘的背离令人联想起过往下行信号；也有人关注信贷质量，并认为未实现亏损未必等于危机。", "url": "https://x.com/i/trending/2112308655303327781", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-19T22:30:56.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Metro Ads with Portraits of Scientists", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Imagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "China has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian. The initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["Celebrity"], "updated_at": "2026-10-21T07:40:42.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕：纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "body_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery.\n\nExperts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕：纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。\n\n第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。\n\n首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112405151768100963", "domain": "中国", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Threatening Remarks", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr. labeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Philippine Senators Push to Expel Chinese Ambassador Over Threatening Remarks.\n\nChinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。\n\n中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:16:46.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国跟踪靠近争议南沙礁盘的美舰", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国跟踪靠近争议南沙礁盘的美舰。\n\n周二早间，一艘美军濒海战斗舰驶入中方所称仙宾礁附近水域，北京派出力量抵近监控。\n\n中国人民解放军海军指责美舰「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾反驳称该舰处于国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。\n\n事件发生在同礁附近近期船只擦碰之后，正值多国在南海存在重叠领土主张。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112579117904535807", "domain": "中国", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光出资纽约矿产加工，保障 AI 芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加码在纽约本土保障 AI 存储芯片关键材料，意在降低对海外供应依赖。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光宣布战略资助 Indium Corporation，在纽约罗马工厂扩大铟等关键矿产精炼，并配套长期供应协议。此举支撑美光 30 亿美元美国半导体供应链投资，应对中国在关键材料生产上的主导地位。尽管有利于国家安全与 AI 增长，当日股价仍因 AI 开支担忧、台湾相关波动与竞争压力下跌约 2%–3%。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光出资纽约矿产加工，保障 AI 芯片原料。\n\n美光加码在纽约本土保障 AI 存储芯片关键材料，意在降低对海外供应依赖。\n\n美光宣布战略资助 Indium Corporation，在纽约罗马工厂扩大铟等关键矿产精炼，并配套长期供应协议。\n\n此举支撑美光 30 亿美元美国半导体供应链投资，应对中国在关键材料生产上的主导地位。尽管有利于国家安全与 AI 增长，当日股价仍因 AI 开支担忧、台湾相关波动与竞争压力下跌约 2%–3%。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112529713906200727", "domain": "中国", "title_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions", "title_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议", "hook_en": "Dame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.", "hook_zh": "这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。", "summary_en": "Greater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture. Critics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "summary_zh": "大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "body_en": "Lincolnshire Mayor Signs Taiwan Partnership Amid Authority Questions.\n\nDame Andrea Jenkyns beamed from a video call, pen in hand, announcing a new deal with Taiwan's Tainan to boost trade and innovation. Online replies quickly pointed out mayors don't handle international agreements.\n\nGreater Lincolnshire's mayor shared images of signing what she called a landmark trade agreement with Tainan, highlighting opportunities in agriculture, tech, and culture.\n\nCritics, including a former council leader, labeled it deluded and beyond her powers, clarifying it's actually a sister-city partnership for local exchanges. Taiwanese media confirmed the first such UK-Taiwan link, while users stressed precise wording to avoid misleading the public on formal trade deals.", "body_zh": "林肯郡市长与台湾台南签署伙伴协议引权限争议。\n\n这位市长在视频连线中高调宣布与台南达成协议，网友很快指出市长无权签署国际条约。\n\n大林肯郡市长分享与台南签署“里程碑贸易协议”的画面，强调农业、科技与文化机会。\n\n包括前议会领袖在内的批评者称其越权，澄清实为姐妹城市式地方交流。台湾媒体确认此为英台此类联系的首例，舆论呼吁措辞准确，避免被误解为正式贸易协定。", "url": "https://x.com/i/trending/2112529713906200727", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:07:49.000Z"}, {"id": "2111675287083651489", "domain": "中国", "title_en": "Philippines and China Clash Over Ambassador's Force Remarks", "title_zh": "菲中因大使“武力”言论再起外交摩擦", "hook_en": "Chinese Ambassador Jing Quan told a Manila forum that China could 'easily win' any force against the Philippines but loves peace instead. Philippine officials saw it as a threat, summoning him to protest.", "hook_zh": "中国驻菲大使称中方若动武可“轻松取胜”但更爱和平；菲方视为威胁并召见抗议。", "summary_en": "On October 15, Ambassador Jing made the comments amid South China Sea tensions, prompting Foreign Secretary Ma. Theresa Lazaro to summon him on October 19 and object strongly. The Chinese Embassy hit back at calls to declare him persona non grata, calling them old tricks and warning of reciprocity. While some senators push the measure and President Marcos Jr. prefers diplomacy, the exchange highlights fragile ties in the West Philippine Sea.", "summary_zh": "10 月 15 日，景泉大使在南海紧张背景下发表上述言论；外长 Lazaro 于 10 月 19 日召见并强烈反对。中国使馆回击要求将其列为不受欢迎人物的呼声，称其为旧伎俩并警告对等措施。部分参议员推动驱逐，马科斯总统更倾向外交沟通，凸显西菲律宾海问题上的脆弱关系。", "body_en": "Philippines and China Clash Over Ambassador's Force Remarks.\n\nChinese Ambassador Jing Quan told a Manila forum that China could 'easily win' any force against the Philippines but loves peace instead. Philippine officials saw it as a threat, summoning him to protest.\n\nOn October 15, Ambassador Jing made the comments amid South China Sea tensions, prompting Foreign Secretary Ma. Theresa Lazaro to summon him on October 19 and object strongly.\n\nThe Chinese Embassy hit back at calls to declare him persona non grata, calling them old tricks and warning of reciprocity. While some senators push the measure and President Marcos Jr. prefers diplomacy, the exchange highlights fragile ties in the West Philippine Sea.", "body_zh": "菲中因大使“武力”言论再起外交摩擦。\n\n中国驻菲大使称中方若动武可“轻松取胜”但更爱和平；菲方视为威胁并召见抗议。\n\n10 月 15 日，景泉大使在南海紧张背景下发表上述言论；外长 Lazaro 于 10 月 19 日召见并强烈反对。\n\n中国使馆回击要求将其列为不受欢迎人物的呼声，称其为旧伎俩并警告对等措施。部分参议员推动驱逐，马科斯总统更倾向外交沟通，凸显西菲律宾海问题上的脆弱关系。", "url": "https://x.com/i/trending/2111675287083651489", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T16:15:02.000Z"}, {"id": "2112595600831033552", "domain": "中国", "title_en": "Micron Shares Slide Amid Chart Warnings and Taiwan Strike", "title_zh": "美光股价回落：图表示警叠加台湾一日罢工", "hook_en": "Micron's stock has tumbled from over $1,250 in June to around $880-$910, leaving traders glued to key support levels like $877-$880.", "hook_zh": "美光股价自 6 月逾 1250 美元跌至约 880–910 美元，交易者紧盯 877–880 美元等关键支撑。", "summary_en": "The memory chipmaker faces a volatile pullback, with analysts spotting bear flag breakdowns on charts and potential drops toward $725 if support fails. Bulls watch for a rebound above $920-$930, backed by strong Q4 results showing massive revenue growth from AI-driven high-bandwidth memory demand and a new $35.16 billion buyback starting December 9. Short-term worries include a one-day strike by Taiwan's Taoyuan union on October 22 over bonuses, adding uncertainty at key manufacturing sites.", "summary_zh": "这家存储芯片商正经历剧烈回调，分析师指出图表上出现熊旗破位迹象，若支撑失守或下看约 725 美元。多头则等待重返 920–930 美元上方，依据包括第四季度强劲业绩——AI 驱动高带宽内存需求带动营收大增——以及自 12 月 9 日起总额约 351.6 亿美元的新回购。短期扰动还包括台湾桃园工会计划 10 月 22 日就奖金问题举行一日罢工，给关键制造节点增添不确定性。", "body_en": "Micron Shares Slide Amid Chart Warnings and Taiwan Strike.\n\nMicron's stock has tumbled from over $1,250 in June to around $880-$910, leaving traders glued to key support levels like $877-$880.\n\nThe memory chipmaker faces a volatile pullback, with analysts spotting bear flag breakdowns on charts and potential drops toward $725 if support fails.\n\nBulls watch for a rebound above $920-$930, backed by strong Q4 results showing massive revenue growth from AI-driven high-bandwidth memory demand and a new $35.16 billion buyback starting December 9. Short-term worries include a one-day strike by Taiwan's Taoyuan union on October 22 over bonuses, adding uncertainty at key manufacturing sites.", "body_zh": "美光股价回落：图表示警叠加台湾一日罢工。\n\n美光股价自 6 月逾 1250 美元跌至约 880–910 美元，交易者紧盯 877–880 美元等关键支撑。\n\n这家存储芯片商正经历剧烈回调，分析师指出图表上出现熊旗破位迹象，若支撑失守或下看约 725 美元。\n\n多头则等待重返 920–930 美元上方，依据包括第四季度强劲业绩——AI 驱动高带宽内存需求带动营收大增——以及自 12 月 9 日起总额约 351.6 亿美元的新回购。短期扰动还包括台湾桃园工会计划 10 月 22 日就奖金问题举行一日罢工，给关键制造节点增添不确定性。", "url": "https://x.com/i/trending/2112595600831033552", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-20T17:33:15.000Z"}, {"id": "2112741572102242464", "domain": "中国", "title_en": "Japan's September Trade Deficit Widens to ¥536.6 Billion", "title_zh": "日本 9 月贸易逆差扩大至 5366 亿日元", "hook_en": "Japan's trade numbers landed with a surprise: a deficit far bigger than expected, even as exports kept climbing on chip and auto demand.", "hook_zh": "日本贸易数据出人意料：逆差远超预期，即便出口仍受芯片与汽车需求支撑继续增长。", "summary_en": "Japan posted a ¥536.6 billion ($3.39 billion) trade deficit in September, beating forecasts of ¥181 billion and marking the fifth straight month in the red. Exports rose 16.7% year-on-year—the 13th month of growth—driven by AI semiconductors and cars, with U.S. shipments up 22.9% and Asia up 17.5%, though below the 20-21% expected. Imports grew 18.9%, also under projections, signaling moderating expansion ahead of the Bank of Japan's policy meeting.", "summary_zh": "日本 9 月贸易逆差达 5366 亿日元（约 33.9 亿美元），远高于预估的 1810 亿日元，连续第五个月赤字。出口同比增长 16.7%，连续第 13 个月扩张，主因 AI 半导体与汽车；对美出口增 22.9%，对亚洲增 17.5%，但仍低于 20%–21% 的预期。进口增 18.9%，同样低于预估，显示扩张势头有所放缓，市场正关注日本央行政策会议。", "body_en": "Japan's September Trade Deficit Widens to ¥536.6 Billion.\n\nJapan's trade numbers landed with a surprise: a deficit far bigger than expected, even as exports kept climbing on chip and auto demand.\n\nJapan posted a ¥536.6 billion ($3.39 billion) trade deficit in September, beating forecasts of ¥181 billion and marking the fifth straight month in the red. Exports rose 16.7% year-on-year—the 13th month of growth—driven by AI semiconductors and cars, with U.S.\n\nshipments up 22.9% and Asia up 17.5%, though below the 20-21% expected. Imports grew 18.9%, also under projections, signaling moderating expansion ahead of the Bank of Japan's policy meeting.", "body_zh": "日本 9 月贸易逆差扩大至 5366 亿日元。\n\n日本贸易数据出人意料：逆差远超预期，即便出口仍受芯片与汽车需求支撑继续增长。\n\n日本 9 月贸易逆差达 5366 亿日元（约 33.9 亿美元），远高于预估的 1810 亿日元，连续第五个月赤字。\n\n出口同比增长 16.7%，连续第 13 个月扩张，主因 AI 半导体与汽车；对美出口增 22.9%，对亚洲增 17.5%，但仍低于 20%–21% 的预期。进口增 18.9%，同样低于预估，显示扩张势头有所放缓，市场正关注日本央行政策会议。", "url": "https://x.com/i/trending/2112741572102242464", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T03:08:30.000Z"}, {"id": "2112450617138659781", "domain": "中国", "title_en": "Wang Yibo Shares North China Leopard Expedition at Beijing Premiere", "title_zh": "王一博北京首映分享华北豹科考经历", "hook_en": "Wang Yibo beamed with pride at the Beijing premiere when he learned his infrared camera had captured a rare North China leopard in the wild.", "hook_zh": "得知红外相机拍到稀有华北豹，王一博在北京首映礼上难掩自豪。", "summary_en": "The Chinese actor and WildAid ambassador attended the media premiere for 'Defenders of the Hidden 2: Land of Leopards' on October 20 in Beijing, recounting his 10-to-15-day high-altitude shoot in Qinghai where he wielded a professional Canon camera for the first time and set up wildlife cams. The series spotlights the North China leopard's habitat struggles and human-wildlife harmony efforts, with the first episode streaming on Tencent Video October 24 and the second on October 31. Yibo urged fans to reject products from endangered species, holding a framed leopard photo amid warm event cheers.", "summary_zh": "这位演员兼 WildAid 大使出席纪录片《隐秘的捍卫者 2：豹之境》媒体首映，讲述在青海海拔地区拍摄 10 至 15 天、首次使用专业佳能相机并布设野生动物相机的经历。系列聚焦华北豹栖息地压力与人兽和谐，第一集 10 月 24 日腾讯视频上线，第二集 10 月 31 日播出。他呼吁拒绝濒危物种制品，现场手持装裱豹照回应粉丝欢呼。", "body_en": "Wang Yibo Shares North China Leopard Expedition at Beijing Premiere.\n\nWang Yibo beamed with pride at the Beijing premiere when he learned his infrared camera had captured a rare North China leopard in the wild.\n\nThe Chinese actor and WildAid ambassador attended the media premiere for 'Defenders of the Hidden 2: Land of Leopards' on October 20 in Beijing, recounting his 10-to-15-day high-altitude shoot in Qinghai where he wielded a professional Canon camera for the first time and set up wildlife cams.\n\nThe series spotlights the North China leopard's habitat struggles and human-wildlife harmony efforts, with the first episode streaming on Tencent Video October 24 and the second on October 31. Yibo urged fans to reject products from endangered species, holding a framed leopard photo amid warm event cheers.", "body_zh": "王一博北京首映分享华北豹科考经历。\n\n得知红外相机拍到稀有华北豹，王一博在北京首映礼上难掩自豪。\n\n这位演员兼 WildAid 大使出席纪录片《隐秘的捍卫者 2：豹之境》媒体首映，讲述在青海海拔地区拍摄 10 至 15 天、首次使用专业佳能相机并布设野生动物相机的经历。\n\n系列聚焦华北豹栖息地压力与人兽和谐，第一集 10 月 24 日腾讯视频上线，第二集 10 月 31 日播出。他呼吁拒绝濒危物种制品，现场手持装裱豹照回应粉丝欢呼。", "url": "https://x.com/i/trending/2112450617138659781", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T17:18:13.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英美波驳斥美防长「阿富汗盟友寥寥」说法", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "皮特·赫格塞斯称真正并肩作战的国家寥寥无几，英波领导人反击。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "英方指出英军阵亡 457 人，仅次于美国；波兰强调 44 名军人牺牲。非美联军死亡总计逾 1100 人。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英美波驳斥美防长「阿富汗盟友寥寥」说法。\n\n皮特·赫格塞斯称真正并肩作战的国家寥寥无几，英波领导人反击。\n\n英方指出英军阵亡 457 人，仅次于美国；波兰强调 44 名军人牺牲。非美联军死亡总计逾 1100 人。\n\n皮特·赫格塞斯称真正并肩作战的国家寥寥无几，英波领导人反击。\n\n综合以上信息，英美波驳斥美防长「阿富汗盟友寥寥」说法一事持续引发关注。\n\n英波方面强调盟友牺牲与集体安全义务，认为防长言论低估了联军贡献。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112533926879125584", "domain": "国际", "title_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe", "title_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势", "hook_en": "In a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.", "hook_zh": "乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。", "summary_en": "Volodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion. Social media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "summary_zh": "泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "body_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe.\n\nIn a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.\n\nVolodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion.\n\nSocial media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "body_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势。\n\n乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。\n\n泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。\n\n社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "url": "https://x.com/i/trending/2112533926879125584", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:26:36.000Z"}, {"id": "2112498208576581993", "domain": "国际", "title_en": "EU Faces External Pressures and Internal Budget Rifts", "title_zh": "欧盟面临外部压力与内部预算裂痕", "hook_en": "A post warning of assaults from Russia, China, and a Trump-led U.S. has people debating Europe's path forward amid real budget battles.", "hook_zh": "有帖文警告俄、中与特朗普治下美国的多重冲击，欧洲路径争论与真实预算博弈交织。", "summary_en": "SandroG991's post described the EU under a multi-front assault—Russia's hybrid warfare, China's economic leverage, and U.S. hostility—urging deeper integration to protect liberal democracy. Supporters like Joe Haslam praised the EU's role in freedoms, while critics slammed the European Commission and pushed for less central power. Meanwhile, Germany demands €400 billion cuts from the proposed €2 trillion 2028-2034 budget, joined by Netherlands, Sweden, and others prioritizing defense over spending, as net contributions like Germany's €20 billion in 2023 fuel tensions ahead of 2026 negotiations.", "summary_zh": "帖文将欧盟描述为面临俄罗斯混合战、中国经济杠杆与美国敌意的多线冲击，呼吁更深一体化以捍卫自由民主。支持者肯定欧盟对自由的作用，批评者则抨击欧委会并主张削减中央权力。与此同时，德国要求对拟议的 2028–2034 年约 2 万亿欧元预算削减 4000 亿欧元，荷兰、瑞典等亦优先防务而非开支；德国 2023 年净出资约 200 亿欧元，令谈判更趋紧张。", "body_en": "EU Faces External Pressures and Internal Budget Rifts.\n\nA post warning of assaults from Russia, China, and a Trump-led U.S. has people debating Europe's path forward amid real budget battles.\n\nSandroG991's post described the EU under a multi-front assault—Russia's hybrid warfare, China's economic leverage, and U.S. hostility—urging deeper integration to protect liberal democracy.\n\nSupporters like Joe Haslam praised the EU's role in freedoms, while critics slammed the European Commission and pushed for less central power. Meanwhile, Germany demands €400 billion cuts from the proposed €2 trillion 2028-2034 budget, joined by Netherlands, Sweden, and others prioritizing defense over spending, as net contributions like Germany's €20 billion in 2023 fuel tensions ahead of 2026 negotiations.", "body_zh": "欧盟面临外部压力与内部预算裂痕。\n\n有帖文警告俄、中与特朗普治下美国的多重冲击，欧洲路径争论与真实预算博弈交织。\n\n帖文将欧盟描述为面临俄罗斯混合战、中国经济杠杆与美国敌意的多线冲击，呼吁更深一体化以捍卫自由民主。\n\n支持者肯定欧盟对自由的作用，批评者则抨击欧委会并主张削减中央权力。与此同时，德国要求对拟议的 2028–2034 年约 2 万亿欧元预算削减 4000 亿欧元，荷兰、瑞典等亦优先防务而非开支；德国 2023 年净出资约 200 亿欧元，令谈判更趋紧张。", "url": "https://x.com/i/trending/2112498208576581993", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T11:01:54.000Z"}, {"id": "2112749239679820040", "domain": "国际", "title_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms", "title_zh": "CNN：特朗普白宫中期选举前内斗加剧", "hook_en": "A Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.", "hook_zh": "特朗普盟友形容白宫氛围极度不信任，“这里谁都不能信”，担忧中期选举失利。", "summary_en": "A CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell. White House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "summary_zh": "CNN 援引官员与盟友描述白宫内的权力竞逐、甩锅与毒性氛围，共和党正为 11 月中期做准备。近期信号包括 Kimberly Guilfoyle 被免去驻希腊大使，以及对肯尼迪中心资金争议的调查。白宫发言人 Davis Ingle 斥为无端猜测，称特朗普专注保住国会多数。《华盛顿邮报》等亦报道助手为选后角色卡位。", "body_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms.\n\nA Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.\n\nA CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell.\n\nWhite House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "body_zh": "CNN：特朗普白宫中期选举前内斗加剧。\n\n特朗普盟友形容白宫氛围极度不信任，“这里谁都不能信”，担忧中期选举失利。\n\nCNN 援引官员与盟友描述白宫内的权力竞逐、甩锅与毒性氛围，共和党正为 11 月中期做准备。近期信号包括 Kimberly Guilfoyle 被免去驻希腊大使，以及对肯尼迪中心资金争议的调查。\n\n白宫发言人 Davis Ingle 斥为无端猜测，称特朗普专注保住国会多数。《华盛顿邮报》等亦报道助手为选后角色卡位。", "url": "https://x.com/i/trending/2112749239679820040", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T03:38:52.000Z"}, {"id": "2112384299999850805", "domain": "国际", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约，点名法国", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人在帕克城欢呼，特朗普称欧洲麻烦或迫使美国疏远北约。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员 Roger Marshall 助选的集会上，特朗普称法国曾是强国却被移民、圣战分子与共产主义者压垮，敦促加强美国边境。他批评美方在北约与援乌上开支过大，称盟友须加码否则面临撤出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪淹没。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约，点名法国。\n\n数万人在帕克城欢呼，特朗普称欧洲麻烦或迫使美国疏远北约。\n\n在为参议员 Roger Marshall 助选的集会上，特朗普称法国曾是强国却被移民、圣战分子与共产主义者压垮，敦促加强美国边境。\n\n他批评美方在北约与援乌上开支过大，称盟友须加码否则面临撤出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪淹没。", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z"}, {"id": "2112302146825949613", "domain": "国际", "title_en": "Republican Lawmakers Criticize Trump Waiver of Russia Sanctions", "title_zh": "共和党议员批评特朗普豁免对俄制裁条款", "hook_en": "Congressman Max Miller, representing a district with thousands of Ukrainian Americans, called out the Trump administration for waiving sanctions meant to punish Russia over Ukraine.", "hook_zh": "选区有大量乌克兰裔选民的众议员马克斯·米勒，公开批评特朗普政府豁免本用于惩罚俄罗斯侵乌的制裁条款。", "summary_en": "Reps. Max Miller of Ohio and Jeff Hurd of Colorado sharply criticized the Trump administration's decision to waive key provisions of the bipartisan Lindsey O. Graham Sanctioning Russia and Iran Act of 2026, which Congress passed in September to cut Russia's war funding through tariffs and economic measures. Trump cited national interests like lowering U.S. energy prices and advancing peace talks, but the lawmakers argued it eases pressure on Moscow amid its ongoing attacks on Ukraine without real concessions. The move has sparked mixed reactions, with some praising the critics and others prioritizing domestic issues, highlighting GOP tensions over Ukraine support and energy costs ahead of midterms.", "summary_zh": "俄亥俄州众议员马克斯·米勒与科罗拉多州杰夫·赫德，尖锐批评特朗普政府豁免两党《2026 年林赛·格雷厄姆制裁俄罗斯与伊朗法》关键条款；该法于 9 月通过，拟以关税与经济手段削弱俄战争资金。特朗普以降低美国能源价格、推动和谈等「国家利益」为由，议员则认为在莫斯科未作实质让步、仍持续攻乌之际放松压力。反应分化：有人赞赏批评声音，有人更看重国内议题，凸显中期选举前共和党内在挺乌与能源成本上的张力。", "body_en": "Republican Lawmakers Criticize Trump Waiver of Russia Sanctions.\n\nCongressman Max Miller, representing a district with thousands of Ukrainian Americans, called out the Trump administration for waiving sanctions meant to punish Russia over Ukraine.\n\nReps. Max Miller of Ohio and Jeff Hurd of Colorado sharply criticized the Trump administration's decision to waive key provisions of the bipartisan Lindsey O. Graham Sanctioning Russia and Iran Act of 2026, which Congress passed in September to cut Russia's war funding through tariffs and economic measures.\n\nTrump cited national interests like lowering U.S. energy prices and advancing peace talks, but the lawmakers argued it eases pressure on Moscow amid its ongoing attacks on Ukraine without real concessions. The move has sparked mixed reactions, with some praising the critics and others prioritizing domestic issues, highlighting GOP tensions over Ukraine support and energy costs ahead of midterms.", "body_zh": "共和党议员批评特朗普豁免对俄制裁条款。\n\n选区有大量乌克兰裔选民的众议员马克斯·米勒，公开批评特朗普政府豁免本用于惩罚俄罗斯侵乌的制裁条款。\n\n俄亥俄州众议员马克斯·米勒与科罗拉多州杰夫·赫德，尖锐批评特朗普政府豁免两党《2026 年林赛·格雷厄姆制裁俄罗斯与伊朗法》关键条款；该法于 9 月通过，拟以关税与经济手段削弱俄战争资金。\n\n特朗普以降低美国能源价格、推动和谈等「国家利益」为由，议员则认为在莫斯科未作实质让步、仍持续攻乌之际放松压力。反应分化：有人赞赏批评声音，有人更看重国内议题，凸显中期选举前共和党内在挺乌与能源成本上的张力。", "url": "https://x.com/i/trending/2112302146825949613", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T22:08:39.000Z"}, {"id": "2112490180208726285", "domain": "国际", "title_en": "Starlink Restrictions Ease Pressure on Russian Supply Highway in Ukraine", "title_zh": "Starlink 限制缓解俄军乌克兰补给公路压力", "hook_en": "Russian bloggers noticed something unusual on the vital R-280 highway: just one truck hit by a Ukrainian drone in two days, a sharp drop they link straight to Starlink slowdowns.", "hook_zh": "俄方博主注意到关键 R-280 公路上两天仅一辆卡车遭乌克兰无人机打击，锐减幅度被直接归因于 Starlink 限速。", "summary_en": "Military bloggers in Russia report fewer Ukrainian drone strikes along the R-280 Novorossiya highway, a key route from Russia to occupied Crimea, with only a single transport vehicle damaged over the past two days. Ukrainian forces say restrictions on Starshield terminals—the military version of Starlink—have crippled their mid-range drone operations up to 150 kilometers behind lines, halting strikes on Russian logistics for troops, ammo, and fuel. While SpaceX's Elon Musk points to U.S. military decisions and President Trump denies any orders, frontline Ukrainian commanders warn the changes feel like a 'nuclear strike,' potentially costing thousands of lives as Russian supply lines recover.", "summary_zh": "俄军事博主称，连接俄罗斯与占领下克里米亚的关键补给线 R-280「新俄罗斯」公路上，乌克兰无人机袭击明显减少，过去两天仅一辆运输车受损。乌方称对 Starshield（军用版 Starlink）终端的限制削弱了后方约 150 公里中程无人机行动，打击俄军人员、弹药与燃油后勤受阻。SpaceX 的埃隆·马斯克指向美军决策，特朗普否认下过相关命令；前线乌军指挥官警告变化「像核打击」，俄补给线恢复或意味着数千人生命代价。", "body_en": "Starlink Restrictions Ease Pressure on Russian Supply Highway in Ukraine.\n\nRussian bloggers noticed something unusual on the vital R-280 highway: just one truck hit by a Ukrainian drone in two days, a sharp drop they link straight to Starlink slowdowns.\n\nMilitary bloggers in Russia report fewer Ukrainian drone strikes along the R-280 Novorossiya highway, a key route from Russia to occupied Crimea, with only a single transport vehicle damaged over the past two days. Ukrainian forces say restrictions on Starshield terminals—the military version of Starlink—have crippled their mid-range drone operations up to 150 kilometers behind lines, halting strikes on Russian logistics for troops, ammo, and fuel.\n\nWhile SpaceX's Elon Musk points to U.S. military decisions and President Trump denies any orders, frontline Ukrainian commanders warn the changes feel like a 'nuclear strike,' potentially costing thousands of lives as Russian supply lines recover.", "body_zh": "Starlink 限制缓解俄军乌克兰补给公路压力。\n\n俄方博主注意到关键 R-280 公路上两天仅一辆卡车遭乌克兰无人机打击，锐减幅度被直接归因于 Starlink 限速。\n\n俄军事博主称，连接俄罗斯与占领下克里米亚的关键补给线 R-280「新俄罗斯」公路上，乌克兰无人机袭击明显减少，过去两天仅一辆运输车受损。\n\n乌方称对 Starshield（军用版 Starlink）终端的限制削弱了后方约 150 公里中程无人机行动，打击俄军人员、弹药与燃油后勤受阻。SpaceX 的埃隆·马斯克指向美军决策，特朗普否认下过相关命令；前线乌军指挥官警告变化「像核打击」，俄补给线恢复或意味着数千人生命代价。", "url": "https://x.com/i/trending/2112490180208726285", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T10:29:10.000Z"}, {"id": "2112660061600309523", "domain": "国际", "title_en": "U.S. Security Officials Quietly Advise States on Midterm Election Risks", "title_zh": "美安全官员低调向多州通报中期选举风险", "hook_en": "A small group of Defense Department officials has spent months discreetly consulting with governors and lawmakers in 10 states, preparing for scenarios like federal troops at polling places.", "hook_zh": "一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。", "summary_en": "Roughly 10 current and former officials have advised bipartisan election administrators and members of Congress on potential Trump administration actions, such as immigration agents at polls or attempts to nullify results over fraud claims. The effort focuses on closely contested states that could sway congressional control, with participants citing concerns for election integrity and speaking anonymously due to retaliation fears. Reactions split sharply, with some praising it as vital contingency planning and others questioning the unelected group's secretive role amid broader tensions over federal versus state authority.", "summary_zh": "约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "body_en": "U.S. Security Officials Quietly Advise States on Midterm Election Risks.\n\nA small group of Defense Department officials has spent months discreetly consulting with governors and lawmakers in 10 states, preparing for scenarios like federal troops at polling places.\n\nRoughly 10 current and former officials have advised bipartisan election administrators and members of Congress on potential Trump administration actions, such as immigration agents at polls or attempts to nullify results over fraud claims.\n\nThe effort focuses on closely contested states that could sway congressional control, with participants citing concerns for election integrity and speaking anonymously due to retaliation fears. Reactions split sharply, with some praising it as vital contingency planning and others questioning the unelected group's secretive role amid broader tensions over federal versus state authority.", "body_zh": "美安全官员低调向多州通报中期选举风险。\n\n一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。\n\n约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。\n\n重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "url": "https://x.com/i/trending/2112660061600309523", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T09:36:45.000Z"}, {"id": "2112442700796690870", "domain": "国际", "title_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally", "title_zh": "乌克兰是否算美国「盟友」引网络激辩", "hook_en": "Congresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.", "hook_zh": "众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。", "summary_en": "The argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation. Posts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "summary_zh": "争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "body_en": "Online Debate Heats Up Over Ukraine's Status as U.S. Ally.\n\nCongresswoman Madeleine Dean called Ukraine a key ally amid Washington's cooling ties with Kyiv. Conservative voices fired back, questioning any formal bond.\n\nThe argument centers on whether Ukraine counts as a U.S. ally, with no mutual defense treaty, NATO membership, or Major Non-NATO Ally designation.\n\nPosts clash over history too: Ukraine inherited Soviet nukes in 1991, gave them up under the 1994 Budapest Memorandum for security promises from the U.S., U.K., and Russia—but those pledges didn't stop invasions in 2014 or 2022. Recent tensions spiked in mid-October 2026 when President Trump criticized Zelenskyy, eased Russia sanctions, and pushed for peace, cooling U.S.-Ukraine relations and fueling views of Ukraine as either a vital partner or a non-ally in a pricey proxy war.", "body_zh": "乌克兰是否算美国「盟友」引网络激辩。\n\n众议员玛德琳·迪恩称乌克兰是关键盟友，恰逢华盛顿与基辅关系降温；保守派则追问有无正式同盟关系。\n\n争论核心在于乌克兰是否算美国盟友：双方并无共同防御条约、北约成员身份或「主要非北约盟友」认定。\n\n历史也成焦点：乌克兰 1991 年继承苏联核武，却依 1994 年《布达佩斯备忘录》放弃核武，换取美英俄安全承诺，但未能阻止 2014 与 2022 年入侵。2026 年 10 月中旬特朗普批评泽连斯基、放松对俄制裁并推动和谈，美乌关系降温，网络上「关键伙伴」与「昂贵代理人战争中的非盟友」两种叙事激烈对撞。", "url": "https://x.com/i/trending/2112442700796690870", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T20:56:58.000Z"}, {"id": "2112290595213554074", "domain": "国际", "title_en": "Ireland Debates Reforming Triple Lock on Peacekeeping Deployments", "title_zh": "爱尔兰辩论改革维和「三重锁」部署机制", "hook_en": "Taoiseach Micheál Martin fired back in the Dáil: 'How dare you lecture me about Irish neutrality? Russia should not have a veto on Irish participation in peacekeeping.' The exchange captured the chamber's raw tension over neutrality's future.", "hook_zh": "总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。", "summary_en": "The Irish government is advancing the Defence (Amendment) Bill to scrap the UN mandate requirement in the Triple Lock, which currently needs government approval, a Dáil vote, and UN backing for deploying over 12 Defence Forces members abroad. Proponents like Martin argue it prevents vetoes by powers like Russia or China, safeguarding missions such as Ireland's in Lebanon amid UN gridlock since 2014. Opposition leaders, including Mary Lou McDonald and Peadar Tóibín, decry it as a drift from peacekeeping to EU-aligned military action and demand a referendum, with TDs waving 'Save Neutrality' signs amid public protests.", "summary_zh": "爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "body_en": "Ireland Debates Reforming Triple Lock on Peacekeeping Deployments.\n\nTaoiseach Micheál Martin fired back in the Dáil: 'How dare you lecture me about Irish neutrality? Russia should not have a veto on Irish participation in peacekeeping.' The exchange captured the chamber's raw tension over neutrality's future.\n\nThe Irish government is advancing the Defence (Amendment) Bill to scrap the UN mandate requirement in the Triple Lock, which currently needs government approval, a Dáil vote, and UN backing for deploying over 12 Defence Forces members abroad.\n\nProponents like Martin argue it prevents vetoes by powers like Russia or China, safeguarding missions such as Ireland's in Lebanon amid UN gridlock since 2014. Opposition leaders, including Mary Lou McDonald and Peadar Tóibín, decry it as a drift from peacekeeping to EU-aligned military action and demand a referendum, with TDs waving 'Save Neutrality' signs amid public protests.", "body_zh": "爱尔兰辩论改革维和「三重锁」部署机制。\n\n总理马丁在议会回击：「你凭什么教训我爱尔兰中立？俄罗斯不该对爱尔兰参与维和拥有否决权。」现场气氛火药味十足。\n\n爱尔兰政府推进《国防（修正）法案》，拟废除「三重锁」中的联合国授权要求——目前向海外部署超过 12 名国防军须经政府批准、议会表决与联合国背书。\n\n马丁等支持者称可防止俄中等大国否决，保障如黎巴嫩维和等任务，尤其在 2014 年以来联合国僵局下。反对派包括玛丽·卢·麦克唐纳与 Peadar Tóibín 指责此举偏离维和、倒向欧盟军事行动，要求公投；议员挥舞「保卫中立」标语，民间亦有抗议。", "url": "https://x.com/i/trending/2112290595213554074", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T09:30:08.000Z"}, {"id": "2112813401197998100", "domain": "国际", "title_en": "Zelenskyy Mourns Lives and Childhood Lost in Ukraine War", "title_zh": "泽连斯基缅怀战争中逝去的生命与童年", "hook_en": "In Oslo, Zelenskyy spoke from the heart about children robbed of their childhood and lives slipping away daily from Russian attacks.", "hook_zh": "在奥斯陆，泽连斯基动情谈到孩子被夺走的童年，以及俄军袭击下每天消逝的生命。", "summary_en": "On October 20, Ukrainian President Volodymyr Zelenskyy addressed a press conference after meetings with U.S. envoy Steve Witkoff, Norwegian Prime Minister Jonas Gahr Støre, and Finnish President Alexander Stubb. He affirmed Ukraine is not losing the war but highlighted the heavy toll of lost lives, time, and normal childhoods, urging a quick end to the conflict. Zelenskyy praised his soldiers' strength and expressed hope for help from American and European partners toward peace talks and ceasefires. Reactions varied, with some voicing strong support and others calling for negotiations amid the mounting human cost.", "summary_zh": "10 月 20 日，乌克兰总统泽连斯基在会见美特使史蒂夫·威特科夫、挪威首相斯特勒与芬兰总统斯图布后举行记者会。他强调乌克兰并未输掉战争，但指出生命、时间与正常童年代价沉重，呼吁尽快结束冲突。泽连斯基赞扬士兵坚强，并希望美欧伙伴协助迈向和谈与停火。反应不一：有人强烈声援，也有人因人道代价催促谈判。", "body_en": "Zelenskyy Mourns Lives and Childhood Lost in Ukraine War.\n\nIn Oslo, Zelenskyy spoke from the heart about children robbed of their childhood and lives slipping away daily from Russian attacks.\n\nOn October 20, Ukrainian President Volodymyr Zelenskyy addressed a press conference after meetings with U.S. envoy Steve Witkoff, Norwegian Prime Minister Jonas Gahr Støre, and Finnish President Alexander Stubb.\n\nHe affirmed Ukraine is not losing the war but highlighted the heavy toll of lost lives, time, and normal childhoods, urging a quick end to the conflict. Zelenskyy praised his soldiers' strength and expressed hope for help from American and European partners toward peace talks and ceasefires. Reactions varied, with some voicing strong support and others calling for negotiations amid the mounting human cost.", "body_zh": "泽连斯基缅怀战争中逝去的生命与童年。\n\n在奥斯陆，泽连斯基动情谈到孩子被夺走的童年，以及俄军袭击下每天消逝的生命。\n\n10 月 20 日，乌克兰总统泽连斯基在会见美特使史蒂夫·威特科夫、挪威首相斯特勒与芬兰总统斯图布后举行记者会。他强调乌克兰并未输掉战争，但指出生命、时间与正常童年代价沉重，呼吁尽快结束冲突。\n\n泽连斯基赞扬士兵坚强，并希望美欧伙伴协助迈向和谈与停火。反应不一：有人强烈声援，也有人因人道代价催促谈判。", "url": "https://x.com/i/trending/2112813401197998100", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T07:53:42.000Z"}, {"id": "2112363184577191956", "domain": "体育", "title_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest", "title_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛", "hook_en": "As riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.", "hook_zh": "巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。", "summary_en": "The Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S. State Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "summary_zh": "匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "body_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest.\n\nAs riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.\n\nThe Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S.\n\nState Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "body_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛。\n\n巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。\n\n匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。\n\n圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "url": "https://x.com/i/trending/2112363184577191956", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T05:34:34.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112326602743050735", "domain": "体育", "title_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series", "title_zh": "小球市进世界大赛，MLB 球迷再议薪资帽", "hook_en": "The Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.", "hook_zh": "密尔沃基酿酒人横扫道奇进联盟冠军赛后，两支低支出球队会师世界大赛，重新点燃「大联盟要不要薪资帽」讨论。", "summary_en": "Brewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion. Owners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "summary_zh": "薪资排名第 19 的酿酒人四场淘汰高支出道奇，联盟冠军赛收视 753 万——2015 年以来最佳，并将对阵光芒争夺首次总冠军。资方提议 2027 年起硬帽约 2.453 亿美元、下限约 1.712 亿以促平衡，球员指其压低工资加以拒绝。海盗等小球市球迷欢迎限制囤人；批评者称区位与文化仍左右球星去向，酿酒人此番证明精明开支可行，尽管与道奇预计约 4.33 亿薪资差距巨大。", "body_en": "MLB Fans Debate Salary Cap as Small-Market Teams Reach World Series.\n\nThe Milwaukee Brewers swept the Dodgers in the NLCS, sending two low-spending teams to the World Series and fueling fresh talk about whether MLB needs a salary cap.\n\nBrewers, with the 19th-ranked payroll, beat the high-spending Dodgers in four games, drawing 7.53 million viewers—the best LCS audience since 2015—and now face the Rays for a first-time champion.\n\nOwners propose a $245.3 million hard cap and $171.2 million floor starting 2027 to boost balance, but players reject it as a wage suppressor. Small-market fans like Pirates supporters cheer the idea to limit talent hoarding, while critics say location and culture still sway stars, and Brewers' run proves smart spending works amid wide payroll gaps like the Dodgers' $433 million projection.", "body_zh": "小球市进世界大赛，MLB 球迷再议薪资帽。\n\n密尔沃基酿酒人横扫道奇进联盟冠军赛后，两支低支出球队会师世界大赛，重新点燃「大联盟要不要薪资帽」讨论。\n\n薪资排名第 19 的酿酒人四场淘汰高支出道奇，联盟冠军赛收视 753 万——2015 年以来最佳，并将对阵光芒争夺首次总冠军。资方提议 2027 年起硬帽约 2.453 亿美元、下限约 1.712 亿以促平衡，球员指其压低工资加以拒绝。\n\n海盗等小球市球迷欢迎限制囤人；批评者称区位与文化仍左右球星去向，酿酒人此番证明精明开支可行，尽管与道奇预计约 4.33 亿薪资差距巨大。", "url": "https://x.com/i/trending/2112326602743050735", "category": "Sports", "topics": ["MLB"], "updated_at": "2026-10-21T05:20:54.000Z"}, {"id": "2112324174198739085", "domain": "体育", "title_en": "Soccer vs. American Football Fan Debate Explodes Over Global Popularity Video", "title_zh": "足球与美式橄榄球球迷为「全球人气」视频激烈互怼", "hook_en": "A video ranking the world's top sports from 1900 to 2026 has fans fiercely defending their favorites, with soccer's massive global following clashing against the NFL's revenue dominance.", "hook_zh": "一段排列 1900–2026 世界热门运动的视频让粉丝力挺所爱：足球的全球拥趸对上 NFL 的营收统治力。", "summary_en": "The video shows soccer leading with 3.5 to 4 billion fans worldwide, while American football trails in the low hundreds of millions on fan count lists. Yet the NFL tops all sports in revenue, distributing over $14 billion annually, prompting arguments over whether global popularity or financial power defines a sport's success. Soccer supporters call the NFL a 'small regional sport' like badminton, while U.S. fans prioritize domestic viewership, high salaries, and market strength over international surveys. Both sides stick to their preferred metrics in this ongoing rivalry.", "summary_zh": "视频显示足球以全球约 35–40 亿粉丝领先，美式橄榄球粉丝量仅数亿级；但 NFL 营收居所有运动之首，年分账逾 140 亿美元，引发「人气还是金流定义成功」之争。足球拥趸称 NFL 像羽毛球般「区域小项」，美国粉丝则更看重国内收视、高薪与市场实力而非国际调查。双方各执偏好指标，恩怨难休。", "body_en": "Soccer vs. American Football Fan Debate Explodes Over Global Popularity Video.\n\nA video ranking the world's top sports from 1900 to 2026 has fans fiercely defending their favorites, with soccer's massive global following clashing against the NFL's revenue dominance.\n\nThe video shows soccer leading with 3.5 to 4 billion fans worldwide, while American football trails in the low hundreds of millions on fan count lists. Yet the NFL tops all sports in revenue, distributing over $14 billion annually, prompting arguments over whether global popularity or financial power defines a sport's success.\n\nSoccer supporters call the NFL a 'small regional sport' like badminton, while U.S. fans prioritize domestic viewership, high salaries, and market strength over international surveys. Both sides stick to their preferred metrics in this ongoing rivalry.", "body_zh": "足球与美式橄榄球球迷为「全球人气」视频激烈互怼。\n\n一段排列 1900–2026 世界热门运动的视频让粉丝力挺所爱：足球的全球拥趸对上 NFL 的营收统治力。\n\n视频显示足球以全球约 35–40 亿粉丝领先，美式橄榄球粉丝量仅数亿级；但 NFL 营收居所有运动之首，年分账逾 140 亿美元，引发「人气还是金流定义成功」之争。足球拥趸称 NFL 像羽毛球般「区域小项」，美国粉丝则更看重国内收视、高薪与市场实力而非国际调查。\n\n双方各执偏好指标，恩怨难休。", "url": "https://x.com/i/trending/2112324174198739085", "category": "Sports", "topics": ["American Football"], "updated_at": "2026-10-19T23:30:44.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.\n\nOther games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112718297158332458", "domain": "体育", "title_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener", "title_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛", "hook_en": "On a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.", "hook_zh": "底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。", "summary_en": "The league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers. While some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "summary_zh": "2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "body_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener.\n\nOn a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.\n\nThe league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers.\n\nWhile some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "body_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛。\n\n底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。\n\n2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。\n\n部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "url": "https://x.com/i/trending/2112718297158332458", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T01:36:46.000Z"}, {"id": "2112623559877042588", "domain": "体育", "title_en": "USL Unveils Unified Brand with 'United for Soccer' Slogan", "title_zh": "USL 发布统一品牌，口号「为足球联合」", "hook_en": "The USL just rolled out a fresh look designed to tie together its eight leagues and thousands of players, coaches, and fans across the country.", "hook_zh": "美国足球联赛推出全新视觉，意在串联旗下八条联赛以及全国成千上万球员、教练与球迷。", "summary_en": "On Tuesday, the United Soccer League introduced a new brand identity under the slogan “United for Soccer,” featuring a redesigned mark inspired by soccer ball geometry and an upward stair-step in the “S” for progress. This visual refresh, using consistent USL Blue and soccer-net icons, connects men’s leagues from the upcoming USL Premier in 2028 down to youth levels, plus women’s leagues like Gainbridge Super League and W League. It supports planned promotion and relegation across three professional men’s tiers, creating clearer pathways, with full rollout starting January 2027. Fans and observers have mixed reactions, from excitement over grassroots growth to questions about the design and timeline.", "summary_zh": "周二，United Soccer League 以口号「United for Soccer」发布新品牌标识，设计灵感来自足球几何结构，「S」中向上阶梯象征进步。统一的 USL 蓝与球网图标连接从 2028 年将推出的男子 USL Premier 到青少年层级，以及女子 Gainbridge Super League、W League 等。品牌亦支撑三层男子职业联赛的升降级规划，理顺上升通道，全面落地自 2027 年 1 月起。球迷与观察者反应不一：有人为草根成长欢呼，也有人对设计与时间表存疑。", "body_en": "USL Unveils Unified Brand with 'United for Soccer' Slogan.\n\nThe USL just rolled out a fresh look designed to tie together its eight leagues and thousands of players, coaches, and fans across the country.\n\nOn Tuesday, the United Soccer League introduced a new brand identity under the slogan “United for Soccer,” featuring a redesigned mark inspired by soccer ball geometry and an upward stair-step in the “S” for progress. This visual refresh, using consistent USL Blue and soccer-net icons, connects men’s leagues from the upcoming USL Premier in 2028 down to youth levels, plus women’s leagues like Gainbridge Super League and W League.\n\nIt supports planned promotion and relegation across three professional men’s tiers, creating clearer pathways, with full rollout starting January 2027. Fans and observers have mixed reactions, from excitement over grassroots growth to questions about the design and timeline.", "body_zh": "USL 发布统一品牌，口号「为足球联合」。\n\n美国足球联赛推出全新视觉，意在串联旗下八条联赛以及全国成千上万球员、教练与球迷。\n\n周二，United Soccer League 以口号「United for Soccer」发布新品牌标识，设计灵感来自足球几何结构，「S」中向上阶梯象征进步。统一的 USL 蓝与球网图标连接从 2028 年将推出的男子 USL Premier 到青少年层级，以及女子 Gainbridge Super League、W League 等。\n\n品牌亦支撑三层男子职业联赛的升降级规划，理顺上升通道，全面落地自 2027 年 1 月起。球迷与观察者反应不一：有人为草根成长欢呼，也有人对设计与时间表存疑。", "url": "https://x.com/i/trending/2112623559877042588", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T00:50:39.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌。\n\n拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。\n\n休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112355020591046930", "domain": "体育", "title_en": "WNBA Players Exit Court Before Finals Anthem, Drawing Criticism", "title_zh": "WNBA 总决赛两队国歌前离场惹议", "hook_en": "Atlanta Dream and Golden State Valkyries players walked off the court just before the national anthem in Game 1, returning right after it finished. The routine repeated in Game 2, leaving many fans upset.", "hook_zh": "亚特兰大梦想与金州女武神在 Chase Center 总决赛中，按惯常赛前流程于国歌响起前走下球场。", "summary_en": "The WNBA rulebook requires players to stand during the anthem, but reports say the league stopped enforcing it years ago, turning court exits into a pregame habit for many teams. Critics like Sage Steele called it ignorant, while others linked low Game 1 viewership and the anthem absences to identity politics pushing away fans attracted by stars like Caitlin Clark. Despite sharp salary rises to $1.4 million max under the new deal, some labeled the actions entitled amid America's support for women's sports; the league has not commented.", "summary_zh": "两队热身后天歌前进入更衣室，国歌后再返回——女武神自建队沿用，梦想亦多年如此，与联盟约 2017–2020 年放松相关规范后的常见做法一致。批评者如 Sage Steele 称「无知地冲下场」，Clay Travis 归咎身份政治疏远凯琳·克拉克球迷；社交媒体以 CBA 薪资可达 140 万美元指球员「 entitlement」。规则书要求沿边线站立，但球队与联盟未置评，亦未宣布纪律，系列赛第三场将转战亚特兰大。", "body_en": "WNBA Players Exit Court Before Finals Anthem, Drawing Criticism.\n\nAtlanta Dream and Golden State Valkyries players walked off the court just before the national anthem in Game 1, returning right after it finished. The routine repeated in Game 2, leaving many fans upset.\n\nThe WNBA rulebook requires players to stand during the anthem, but reports say the league stopped enforcing it years ago, turning court exits into a pregame habit for many teams.\n\nCritics like Sage Steele called it ignorant, while others linked low Game 1 viewership and the anthem absences to identity politics pushing away fans attracted by stars like Caitlin Clark. Despite sharp salary rises to $1.4 million max under the new deal, some labeled the actions entitled amid America's support for women's sports; the league has not commented.", "body_zh": "WNBA 总决赛两队国歌前离场惹议。\n\n亚特兰大梦想与金州女武神在 Chase Center 总决赛中，按惯常赛前流程于国歌响起前走下球场。\n\n两队热身后天歌前进入更衣室，国歌后再返回——女武神自建队沿用，梦想亦多年如此，与联盟约 2017–2020 年放松相关规范后的常见做法一致。批评者如 Sage Steele 称「无知地冲下场」，Clay Travis 归咎身份政治疏远凯琳·克拉克球迷；社交媒体以 CBA 薪资可达 140 万美元指球员「 entitlement」。\n\n规则书要求沿边线站立，但球队与联盟未置评，亦未宣布纪律，系列赛第三场将转战亚特兰大。", "url": "https://x.com/i/trending/2112355020591046930", "category": "Sports", "topics": ["WNBA"], "updated_at": "2026-10-21T09:36:27.000Z"}, {"id": "2112321756438417544", "domain": "体育", "title_en": "Bay Area Loses Pro Sports Teams to Las Vegas Amid Ownership Debates", "title_zh": "湾区职业球队接连迁往拉斯维加斯，所有权争议再起", "hook_en": "Longtime Oakland fans watched their Athletics and Raiders pack up for Las Vegas, leaving empty seats and lingering questions about why local heroes didn't step in to save them.", "hook_zh": "奥克兰球迷眼看运动家与突袭者迁往拉斯维加斯，空荡看台背后是「本地富豪为何不出手挽留」的追问。", "summary_en": "The Bay Area has lost the Oakland Athletics and Raiders to Las Vegas, with fans pointing to owner John Fisher's refusal to sell the A's despite a generous offer from Warriors owner Joe Lacob to keep the team local. Critics note the teams weren't truly put up for sale, as owners chased public funding in Vegas instead, including up to $380 million for the A's new 2028 ballpark. Oakland rejected stadium subsidies based on economic studies, while Vegas thrives on out-of-town fans—62 percent of Raiders attendees—and tourism boosts. The moves highlight tensions over ownership choices, public money, and a tech-rich region that couldn't retain its teams.", "summary_zh": "湾区已失去奥克兰运动家与突袭者至拉斯维加斯；粉丝指出老板约翰·费舍尔拒绝出售运动家，即便勇士老板乔·拉科布曾开出优厚报价希望球队留在本地。批评者称球队并未真正挂牌出售，老板更追逐维加斯的公共资金，包括运动家 2028 年新球场最高约 3.8 亿美元补贴。奥克兰曾依经济研究拒绝球场补贴，而维加斯靠外来球迷——突袭者观众约 62% 来自外地——与旅游拉动。事件凸显所有权选择、公帑使用，以及科技富裕地区仍难留住球队的张力。", "body_en": "Bay Area Loses Pro Sports Teams to Las Vegas Amid Ownership Debates.\n\nLongtime Oakland fans watched their Athletics and Raiders pack up for Las Vegas, leaving empty seats and lingering questions about why local heroes didn't step in to save them.\n\nThe Bay Area has lost the Oakland Athletics and Raiders to Las Vegas, with fans pointing to owner John Fisher's refusal to sell the A's despite a generous offer from Warriors owner Joe Lacob to keep the team local. Critics note the teams weren't truly put up for sale, as owners chased public funding in Vegas instead, including up to $380 million for the A's new 2028 ballpark.\n\nOakland rejected stadium subsidies based on economic studies, while Vegas thrives on out-of-town fans—62 percent of Raiders attendees—and tourism boosts. The moves highlight tensions over ownership choices, public money, and a tech-rich region that couldn't retain its teams.", "body_zh": "湾区职业球队接连迁往拉斯维加斯，所有权争议再起。\n\n奥克兰球迷眼看运动家与突袭者迁往拉斯维加斯，空荡看台背后是「本地富豪为何不出手挽留」的追问。\n\n湾区已失去奥克兰运动家与突袭者至拉斯维加斯；粉丝指出老板约翰·费舍尔拒绝出售运动家，即便勇士老板乔·拉科布曾开出优厚报价希望球队留在本地。批评者称球队并未真正挂牌出售，老板更追逐维加斯的公共资金，包括运动家 2028 年新球场最高约 3.8 亿美元补贴。\n\n奥克兰曾依经济研究拒绝球场补贴，而维加斯靠外来球迷——突袭者观众约 62% 来自外地——与旅游拉动。事件凸显所有权选择、公帑使用，以及科技富裕地区仍难留住球队的张力。", "url": "https://x.com/i/trending/2112321756438417544", "category": "Sports", "topics": ["Sports"], "updated_at": "2026-10-20T02:45:02.000Z"}, {"id": "2112595603800662270", "domain": "体育", "title_en": "College Football Coaches Split on 24-Team Playoff Expansion", "title_zh": "大学橄榄球教练对 24 队季后赛扩军意见分裂", "hook_en": "Kentucky coach Will Stein dreams of a playoff game lighting up Kroger Field, while Central Michigan's Matt Drinkall sees the sport spiraling into a 'smoldering dumpster fire.' Their clashing views capture the tension as expansion nears.", "hook_zh": "肯塔基教练威尔·斯坦梦想主场亮起季后赛灯，中密歇根的马特·德林克尔却称这项运动正滑向「冒烟的垃圾堆」。", "summary_en": "The College Football Playoff eyes growth to 24 teams possibly starting in 2027, with 19 at-large bids, spots for Power Four conference champs, and one for the top Group of Six team—likely ditching conference title games for on-campus early rounds. Stein dismisses critics who say regular-season games will lose meaning, insisting every matchup counts and smaller programs gain real postseason shots. Drinkall blasts the changes as short-term cash grabs that erode the game's traditions, likening them to boxing's chaotic past. The debate weighs broader access against keeping the regular season's edge sharp.", "summary_zh": "大学橄榄球季后赛拟自约 2027 年起扩至 24 队：19 个外卡、Power Four 冠军席位，以及一个顶级 Group of Six 席位，并可能取消联盟冠军赛、把早期轮次放回校园。斯坦驳斥「常规赛将失去意义」的批评，称每场仍关键、小球会也有真实季后赛机会。德林克尔则抨击为短视捞金，侵蚀传统，并类比拳击历史上的混乱。辩论焦点在：扩大准入，还是保住常规赛的锋利度。", "body_en": "College Football Coaches Split on 24-Team Playoff Expansion.\n\nKentucky coach Will Stein dreams of a playoff game lighting up Kroger Field, while Central Michigan's Matt Drinkall sees the sport spiraling into a 'smoldering dumpster fire.' Their clashing views capture the tension as expansion nears.\n\nThe College Football Playoff eyes growth to 24 teams possibly starting in 2027, with 19 at-large bids, spots for Power Four conference champs, and one for the top Group of Six team—likely ditching conference title games for on-campus early rounds. Stein dismisses critics who say regular-season games will lose meaning, insisting every matchup counts and smaller programs gain real postseason shots.\n\nDrinkall blasts the changes as short-term cash grabs that erode the game's traditions, likening them to boxing's chaotic past. The debate weighs broader access against keeping the regular season's edge sharp.", "body_zh": "大学橄榄球教练对 24 队季后赛扩军意见分裂。\n\n肯塔基教练威尔·斯坦梦想主场亮起季后赛灯，中密歇根的马特·德林克尔却称这项运动正滑向「冒烟的垃圾堆」。\n\n大学橄榄球季后赛拟自约 2027 年起扩至 24 队：19 个外卡、Power Four 冠军席位，以及一个顶级 Group of Six 席位，并可能取消联盟冠军赛、把早期轮次放回校园。斯坦驳斥「常规赛将失去意义」的批评，称每场仍关键、小球会也有真实季后赛机会。\n\n德林克尔则抨击为短视捞金，侵蚀传统，并类比拳击历史上的混乱。辩论焦点在：扩大准入，还是保住常规赛的锋利度。", "url": "https://x.com/i/trending/2112595603800662270", "category": "Sports", "topics": ["NCAA Football"], "updated_at": "2026-10-21T04:18:08.000Z"}, {"id": "2111931440430739802", "domain": "体育", "title_en": "Eagles Fans Lament Injury Wave Hitting 2026 Season Hard", "title_zh": "老鹰球迷哀叹伤病潮重创 2026 赛季", "hook_en": "Philadelphia Eagles fans are pouring out their hearts over a brutal string of injuries that's left their team battered and their offense sputtering.", "hook_zh": "费城老鹰球迷吐槽连串伤病让球队千疮百孔、进攻失灵。", "summary_en": "Quarterback Jalen Hurts is on injured reserve with a calf blood clot, sidelining him for at least four games, while running back Saquon Barkley nurses a hamstring issue and edge rusher Nolan Smith deals with a concussion from the Week 6 loss to Carolina. The Eagles rank near the bottom of the NFL at 31st in total offense, 29th in points, and 28th in passing, marking their worst start since 2000 in key metrics. At 2-4, fans vent frustration with cries of voodoo curses and jokes about a nearby substation, but the sheer volume of injuries has everyone watching closely as the team fights to stabilize.", "summary_zh": "四分卫贾伦·赫茨因小腿血栓进伤病名单，至少缺席四场；跑卫萨昆·巴克利跟腱/腘绳肌问题，边锋诺兰·史密斯在第 6 周负于卡罗莱纳后处理脑震荡。老鹰总进攻排 NFL 第 31、得分第 29、传球第 28，多项关键数据为 2000 年以来最差开局之一。战绩 2-4，球迷又是喊「被下了咒」又是拿附近变电站开玩笑，但伤病密度让所有人紧盯球队能否稳住阵脚。", "body_en": "Eagles Fans Lament Injury Wave Hitting 2026 Season Hard.\n\nPhiladelphia Eagles fans are pouring out their hearts over a brutal string of injuries that's left their team battered and their offense sputtering.\n\nQuarterback Jalen Hurts is on injured reserve with a calf blood clot, sidelining him for at least four games, while running back Saquon Barkley nurses a hamstring issue and edge rusher Nolan Smith deals with a concussion from the Week 6 loss to Carolina.\n\nThe Eagles rank near the bottom of the NFL at 31st in total offense, 29th in points, and 28th in passing, marking their worst start since 2000 in key metrics. At 2-4, fans vent frustration with cries of voodoo curses and jokes about a nearby substation, but the sheer volume of injuries has everyone watching closely as the team fights to stabilize.", "body_zh": "老鹰球迷哀叹伤病潮重创 2026 赛季。\n\n费城老鹰球迷吐槽连串伤病让球队千疮百孔、进攻失灵。\n\n四分卫贾伦·赫茨因小腿血栓进伤病名单，至少缺席四场；跑卫萨昆·巴克利跟腱/腘绳肌问题，边锋诺兰·史密斯在第 6 周负于卡罗莱纳后处理脑震荡。\n\n老鹰总进攻排 NFL 第 31、得分第 29、传球第 28，多项关键数据为 2000 年以来最差开局之一。战绩 2-4，球迷又是喊「被下了咒」又是拿附近变电站开玩笑，但伤病密度让所有人紧盯球队能否稳住阵脚。", "url": "https://x.com/i/trending/2111931440430739802", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T06:11:24.000Z"}, {"id": "2112675329613672597", "domain": "娱乐", "title_en": "YouTube Hits Record 14.2% of U.S. TV Viewing Time Over Netflix", "title_zh": "YouTube 占美国电视收视创纪录 14.2%，超越奈飞", "hook_en": "Every day, more Americans turn to YouTube for their TV time, leaving Netflix in the dust according to fresh Nielsen data.", "hook_zh": "尼尔森新数据显示，美国人把更多电视时间交给 YouTube，奈飞份额下滑。", "summary_en": "Nielsen's July 2026 report shows YouTube claiming 14.2% of total U.S. TV viewing, up from 13.4% a year ago, while Netflix dipped to 7.8% from 8.8%. Investor Chamath Palihapitiya shared the chart, explaining he watches YouTube daily and sees Netflix as a dormant subscription due to its high debt and content costs. Viewers praise YouTube's quick content discovery and long-form appeal, though analysts like Joseph Carlson note YouTube's hefty creator payouts offset its low-cost image. Streaming hit 49% of TV time that month, signaling a shift toward flexible, creator-driven platforms.", "summary_zh": "尼尔森 2026 年 7 月报告显示，YouTube 占美国电视总收视 14.2%，高于一年前的 13.4%；奈飞从 8.8% 降至 7.8%。投资人 Chamath Palihapitiya 分享图表，称自己每天看 YouTube，并将奈飞视为高负债与内容成本下的“休眠订阅”。观众称赞 YouTube 发现内容快、长视频吸引力强；分析师提醒其创作者分成也不低。当月流媒体占电视时间 49%。", "body_en": "YouTube Hits Record 14.2% of U.S. TV Viewing Time Over Netflix.\n\nEvery day, more Americans turn to YouTube for their TV time, leaving Netflix in the dust according to fresh Nielsen data.\n\nNielsen's July 2026 report shows YouTube claiming 14.2% of total U.S. TV viewing, up from 13.4% a year ago, while Netflix dipped to 7.8% from 8.8%.\n\nInvestor Chamath Palihapitiya shared the chart, explaining he watches YouTube daily and sees Netflix as a dormant subscription due to its high debt and content costs. Viewers praise YouTube's quick content discovery and long-form appeal, though analysts like Joseph Carlson note YouTube's hefty creator payouts offset its low-cost image. Streaming hit 49% of TV time that month, signaling a shift toward flexible, creator-driven platforms.", "body_zh": "YouTube 占美国电视收视创纪录 14.2%，超越奈飞。\n\n尼尔森新数据显示，美国人把更多电视时间交给 YouTube，奈飞份额下滑。\n\n尼尔森 2026 年 7 月报告显示，YouTube 占美国电视总收视 14.2%，高于一年前的 13.4%；奈飞从 8.8% 降至 7.8%。投资人 Chamath Palihapitiya 分享图表，称自己每天看 YouTube，并将奈飞视为高负债与内容成本下的“休眠订阅”。\n\n观众称赞 YouTube 发现内容快、长视频吸引力强；分析师提醒其创作者分成也不低。当月流媒体占电视时间 49%。", "url": "https://x.com/i/trending/2112675329613672597", "category": "News", "topics": ["Business & Finance", "Movies & TV"], "updated_at": "2026-10-20T22:49:16.000Z"}, {"id": "2112533925117460907", "domain": "娱乐", "title_en": "BBC to Close BBC Three, BBC Scotland TV and Radio 4 Extra in 2027", "title_zh": "BBC 拟明年春季关停 BBC Three、BBC Scotland 与 Radio 4 Extra", "hook_en": "The BBC delivered tough news to staff: linear channels for BBC Three, BBC Scotland, and Radio 4 Extra will end in spring 2027 as savings mount.", "hook_zh": "总经理 Matt Brittin 告知员工：为节省约 5 亿英镑，三套深受喜爱的频道将停播线性信号。", "summary_en": "Facing falling TV licence fee revenue from 25.95 million in 2020 to 23.3 million by March 2026, the BBC plans to save £500 million by 2028 by shifting these services online to iPlayer, BBC Sounds, and Scottish TV channels. The changes include cutting over 100 news jobs to save £5.5 million, part of reducing 1,800 to 2,000 total positions. Reactions split, with John Cleese cheering cuts to 'woke departments' and MP Anna Sabine fearing the erosion of a British institution, while Scottish voices debate local control amid streaming shifts.", "summary_zh": "BBC Three 与 BBC Scotland 将全面转向 iPlayer、YouTube 等线上平台，苏格兰节目也会在 BBC One、Two 播出；Radio 4 Extra 迁至 BBC Sounds，大部分内容数字化保留，线性广播将于 2027 年春结束。此举属两年削减约 1800–2000 岗位（含新闻部门逾 100 人）的节支计划一部分。Brittin 承认对受众与同事的冲击，强调必须适应变化的世界。", "body_en": "BBC to Close BBC Three, BBC Scotland TV and Radio 4 Extra in 2027.\n\nThe BBC delivered tough news to staff: linear channels for BBC Three, BBC Scotland, and Radio 4 Extra will end in spring 2027 as savings mount.\n\nFacing falling TV licence fee revenue from 25.95 million in 2020 to 23.3 million by March 2026, the BBC plans to save £500 million by 2028 by shifting these services online to iPlayer, BBC Sounds, and Scottish TV channels.\n\nThe changes include cutting over 100 news jobs to save £5.5 million, part of reducing 1,800 to 2,000 total positions. Reactions split, with John Cleese cheering cuts to 'woke departments' and MP Anna Sabine fearing the erosion of a British institution, while Scottish voices debate local control amid streaming shifts.", "body_zh": "BBC 拟明年春季关停 BBC Three、BBC Scotland 与 Radio 4 Extra。\n\n总经理 Matt Brittin 告知员工：为节省约 5 亿英镑，三套深受喜爱的频道将停播线性信号。\n\nBBC Three 与 BBC Scotland 将全面转向 iPlayer、YouTube 等线上平台，苏格兰节目也会在 BBC One、Two 播出；Radio 4 Extra 迁至 BBC Sounds，大部分内容数字化保留，线性广播将于 2027 年春结束。\n\n此举属两年削减约 1800–2000 岗位（含新闻部门逾 100 人）的节支计划一部分。Brittin 承认对受众与同事的冲击，强调必须适应变化的世界。", "url": "https://x.com/i/trending/2112533925117460907", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T09:55:52.000Z"}, {"id": "2112465474994737570", "domain": "娱乐", "title_en": "The Grim Lover Unveils Striking Visuals and Bangkok Fansign Event", "title_zh": "《The Grim Lover》释出吸睛视觉，曼谷粉丝见面会将办", "hook_en": "Pooh Krittin channels a mysterious grim reaper with flowing black hair, while Pavel Naret stands poised as a doctor in white – fans can't get enough of their chemistry.", "hook_zh": "Pooh Krittin 饰神秘黑发死神，Pavel Naret 饰白衣医生，粉丝对他们的化学反应欲罢不能。", "summary_en": "The Thai BL series The Grim Lover, starring Krittin as grim reaper Sibsi (Fourteen or Rafah) and Naret as anesthesiologist Vivorn Assarak (Won), adapts a web novel blending fantasy, romance, and drama. It follows Won, who loses his partner in an accident, faces murder accusations, and connects with a reaper bearing his love's face. The show premieres November 28, 2026, on One 31 in Thailand and Netflix worldwide, with a ROAD TO THE GRIM LOVER fansign on November 18 at ICONSIAM HALL in Bangkok – tickets on sale October 30 via THAITICKETMAJOR, featuring meet-and-greets and games. Fans praise the actors' 'lethal visuals' and pairing as 'FourteenWon supremacy.'", "summary_zh": "泰国 BL 剧《The Grim Lover》由 Krittin 饰死神 Sibsi（Fourteen/Rafah）、Naret 饰麻醉医生 Vivorn Assarak（Won），改编融合奇幻、爱情与戏剧的网络小说。故事中 Won 因事故失去伴侣、面临谋杀指控，并与一张酷似爱人面孔的死神产生纠葛。剧集 2026 年 11 月 28 日在泰国 One 31 首播、Netflix 全球上线；11 月 18 日曼谷 ICONSIAM HALL 举办 ROAD TO THE GRIM LOVER 粉丝签名会，门票 10 月 30 日起经 THAITICKETMAJOR 开售。粉丝称视觉「致命」、配对「FourteenWon 至上」。", "body_en": "The Grim Lover Unveils Striking Visuals and Bangkok Fansign Event.\n\nPooh Krittin channels a mysterious grim reaper with flowing black hair, while Pavel Naret stands poised as a doctor in white – fans can't get enough of their chemistry.\n\nThe Thai BL series The Grim Lover, starring Krittin as grim reaper Sibsi (Fourteen or Rafah) and Naret as anesthesiologist Vivorn Assarak (Won), adapts a web novel blending fantasy, romance, and drama. It follows Won, who loses his partner in an accident, faces murder accusations, and connects with a reaper bearing his love's face.\n\nThe show premieres November 28, 2026, on One 31 in Thailand and Netflix worldwide, with a ROAD TO THE GRIM LOVER fansign on November 18 at ICONSIAM HALL in Bangkok – tickets on sale October 30 via THAITICKETMAJOR, featuring meet-and-greets and games. Fans praise the actors' 'lethal visuals' and pairing as 'FourteenWon supremacy.'", "body_zh": "《The Grim Lover》释出吸睛视觉，曼谷粉丝见面会将办。\n\nPooh Krittin 饰神秘黑发死神，Pavel Naret 饰白衣医生，粉丝对他们的化学反应欲罢不能。\n\n泰国 BL 剧《The Grim Lover》由 Krittin 饰死神 Sibsi（Fourteen/Rafah）、Naret 饰麻醉医生 Vivorn Assarak（Won），改编融合奇幻、爱情与戏剧的网络小说。故事中 Won 因事故失去伴侣、面临谋杀指控，并与一张酷似爱人面孔的死神产生纠葛。", "url": "https://x.com/i/trending/2112465474994737570", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T08:52:08.000Z"}, {"id": "2111675291110088931", "domain": "娱乐", "title_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala", "title_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会", "hook_en": "Taylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.", "hook_zh": "泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。", "summary_en": "The 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns. Hannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "summary_zh": "2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "body_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala.\n\nTaylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.\n\nThe 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns.\n\nHannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "body_zh": "泰勒·斯威夫特定制迪奥惊艳 2026 电影学院博物馆晚会。\n\n泰勒·斯威夫特红毯亮相冰蓝色定制迪奥礼服，柔褶与闪亮蝴蝶结在灯光下抢尽目光。\n\n2026 年 10 月 17 日洛杉矶电影学院博物馆晚会筹得逾 1400 万美元，表彰查理兹·塞隆、科尔曼·多明戈与约翰·卡朋特。斯威夫特自 Eras 巡演后首度全乐队演出《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 也以荷叶边胸衣、流苏礼服惊艳。\n\n汉娜·瓦丁厄姆晒与斯威夫特自拍并赞其才华；《英国 Vogue》称其当晚焦点，肖邦钻石超 40 克拉。恐怖主题装饰呼应馆内新展，时尚、音乐与致敬融于一夜。", "url": "https://x.com/i/trending/2111675291110088931", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T03:07:04.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "邝玲玲亮相卡地亚新加坡「Into The Wild」活动。\n\n邝玲玲身着闪亮黑色亮片礼服与戏剧感花卉手套，在丛林风布景前自信亮相。\n\n10 月 19 日，泰国演员邝玲玲出席卡地亚新加坡「Into The Wild」活动，呼应品牌黑豹与动物主题珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配银色链条、手镯与夸张耳环。\n\n粉丝称赞其笑容与气质。沉浸式体验 10 月 21–25 日对公众开放于 Rochester Park 17 号，部分展陈延续至 ION Orchard 至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112506238923608157", "domain": "娱乐", "title_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos", "title_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照", "hook_en": "Pooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.", "hook_zh": "Pooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。", "summary_en": "The promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama. Fans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "summary_zh": "奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。Change2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "body_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos.\n\nPooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.\n\nThe promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama.\n\nFans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "body_zh": "粉丝热捧 Pooh 与 Pavel《死神恋人》宣传照。\n\nPooh Krittin 黑发阴郁死神造型配冷蓝光，Pavel Naret 白衬衫对比鲜明——化学反应已溢出屏幕。\n\n奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（Fourteen/Rafah），Pavel 饰哀悼中的麻醉医生 Vivorn Assarak（Won），改编融合 BL、奇幻、爱情与戏剧的网络小说。粉丝狂赞「致命视觉」与「疯狂」配对，有人称 Pooh「史上最帅死神」。\n\nChange2561 制作，One 31 播出、Netflix 全球上线；粉丝活动 ROAD TO THE GRIM LOVER 定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "url": "https://x.com/i/trending/2112506238923608157", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T11:32:52.000Z"}, {"id": "2111997785189093552", "domain": "娱乐", "title_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views", "title_zh": "Netflix 诺曼·麦克唐纳纪录片引笑声与分歧评价", "hook_en": "Five years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.", "hook_zh": "诺曼·麦克唐纳 61 岁去世五年后，粉丝通过 Netflix 新片重温其冷面天才，笑声夹杂深情回忆。", "summary_en": "Directed by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J. jokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "summary_zh": "贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日首播，长约两小时，以档案片段、家庭录像、照片及其有声书旁白取代新采访。观众赞其为对 SNL 周末更新、O.J. 笑话与传奇节奏感的得体致敬，有人又笑又哭；亦有人觉像剪辑秀、缺新洞见或其更锐利段子。影片亦触及他私下抗癌与不妥协风格，反映其喜剧遗产的持久与争议。", "body_en": "Netflix's Norm Macdonald Documentary Draws Laughs and Mixed Views.\n\nFive years after Norm Macdonald's death at 61, fans are revisiting his deadpan genius through a new Netflix film that mixes laughs with heartfelt memories.\n\nDirected by Judd Apatow, 'Norm: The Tale of Norm Macdonald' premiered October 16 and runs two hours, using archival clips, home videos, photos, and his own audiobook narration instead of new interviews. Viewers praise it as a worthy tribute to his SNL Weekend Update days, O.J.\n\njokes, and legendary timing, with some left laughing and crying over the man they miss. Others call it a clip show lacking fresh insight or his edgier routines, like certain 9/11 bits, though it highlights his private cancer battle and uncompromised style. The responses reflect his enduring, divisive impact on comedy.", "body_zh": "Netflix 诺曼·麦克唐纳纪录片引笑声与分歧评价。\n\n诺曼·麦克唐纳 61 岁去世五年后，粉丝通过 Netflix 新片重温其冷面天才，笑声夹杂深情回忆。\n\n贾德·阿帕图执导的《Norm: The Tale of Norm Macdonald》10 月 16 日首播，长约两小时，以档案片段、家庭录像、照片及其有声书旁白取代新采访。观众赞其为对 SNL 周末更新、O.J. 笑话与传奇节奏感的得体致敬，有人又笑又哭；亦有人觉像剪辑秀、缺新洞见或其更锐利段子。\n\n影片亦触及他私下抗癌与不妥协风格，反映其喜剧遗产的持久与争议。", "url": "https://x.com/i/trending/2111997785189093552", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T05:10:09.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112605676610478278", "domain": "娱乐", "title_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'", "title_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖", "hook_en": "Jaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.", "hook_zh": "「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。", "summary_en": "The Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April. The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "summary_zh": "评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "body_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'.\n\nJaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.\n\nThe Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April.\n\nThe ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "body_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖。\n\n「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。\n\n评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。\n\n典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "url": "https://x.com/i/trending/2112605676610478278", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T18:15:13.000Z"}, {"id": "2112773061053460813", "domain": "娱乐", "title_en": "Global Fans Rally for 'Love On Hire' Premiere Tomorrow", "title_zh": "全球粉丝为《Love On Hire》明日首播集结应援", "hook_en": "Fans everywhere are buzzing with countdown posts like 'LOVE ON HIRE TOMORROW!!!!! T-O-M-O-R-R-O-W' as the Thai GL series gears up for its October 22 debut.", "hook_zh": "粉丝倒计时刷屏「LOVE ON HIRE TOMORROW」，泰国 GL 剧集将于 10 月 22 日开播。", "summary_en": "The WeTV Original romantic comedy stars Ginny Natnicha as poised CEO Chat in an arranged marriage and Jayna Angelina Stevens as Nan, hired to shake it up, blending revenge, fake dating, and real romance across 10 episodes airing Thursdays at 8 p.m. Thailand time. Chinese fans launched a 'Money Flower Bouquet' with 511,000 THB to cover production costs and celebrate Jayna's role, while U.S. supporters push WeTV VIP subscriptions and food projects deliver sushi platters to Ginny. From Bangkok screenings at Siam Paragon to subscription giveaways in the Philippines, Alkeys and global fandoms are turning excitement into coordinated gestures for the duo's latest work.", "summary_zh": "WeTV 原创浪漫喜剧由 Ginny Natnicha 饰演冷静 CEO Chat、Jayna Angelina Stevens 饰演受雇搅局的 Nan，融合复仇、假约会与真感情，共 10 集，每周四泰国时间晚 8 点播出。中国粉丝发起约 51.1 万泰铢「金钱花束」助力制作并庆祝 Jayna 角色；美国支持者推动 WeTV VIP 订阅，餐饮项目则给 Ginny 送上寿司拼盘。从曼谷 Siam Paragon 放映到菲律宾订阅赠礼，Alkeys 与全球粉丝把热情变成有组织应援。", "body_en": "Global Fans Rally for 'Love On Hire' Premiere Tomorrow.\n\nFans everywhere are buzzing with countdown posts like 'LOVE ON HIRE TOMORROW!!!!! T-O-M-O-R-R-O-W' as the Thai GL series gears up for its October 22 debut.\n\nThe WeTV Original romantic comedy stars Ginny Natnicha as poised CEO Chat in an arranged marriage and Jayna Angelina Stevens as Nan, hired to shake it up, blending revenge, fake dating, and real romance across 10 episodes airing Thursdays at 8 p.m. Thailand time.\n\nChinese fans launched a 'Money Flower Bouquet' with 511,000 THB to cover production costs and celebrate Jayna's role, while U.S. supporters push WeTV VIP subscriptions and food projects deliver sushi platters to Ginny. From Bangkok screenings at Siam Paragon to subscription giveaways in the Philippines, Alkeys and global fandoms are turning excitement into coordinated gestures for the duo's latest work.", "body_zh": "全球粉丝为《Love On Hire》明日首播集结应援。\n\n粉丝倒计时刷屏「LOVE ON HIRE TOMORROW」，泰国 GL 剧集将于 10 月 22 日开播。\n\nWeTV 原创浪漫喜剧由 Ginny Natnicha 饰演冷静 CEO Chat、Jayna Angelina Stevens 饰演受雇搅局的 Nan，融合复仇、假约会与真感情，共 10 集，每周四泰国时间晚 8 点播出。\n\n中国粉丝发起约 51.1 万泰铢「金钱花束」助力制作并庆祝 Jayna 角色；美国支持者推动 WeTV VIP 订阅，餐饮项目则给 Ginny 送上寿司拼盘。从曼谷 Siam Paragon 放映到菲律宾订阅赠礼，Alkeys 与全球粉丝把热情变成有组织应援。", "url": "https://x.com/i/trending/2112773061053460813", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T05:13:15.000Z"}, {"id": "2112352804241285515", "domain": "娱乐", "title_en": "Dwayne Johnson Transforms into 70-Year-Old Chicken Man for Lizard Music", "title_zh": "巨石强森变装 70 岁「鸡肉人」出演《Lizard Music》", "hook_en": "Dwayne Johnson stepped out on New York streets looking worlds away from his ripped action-hero self—gray hair, wrinkles, and a bucket hat making him truly unrecognizable as the eccentric Chicken Man.", "hook_zh": "巨石强森现身纽约街头：灰发、皱纹、渔夫帽，几乎认不出他就是古怪的「鸡肉人」。", "summary_en": "He's filming Lizard Music, a live-action/CGI adaptation of Daniel Pinkwater’s 1976 children’s book about a boy who discovers lizards playing otherworldly music on late-night TV and befriends the Chicken Man and his 111-year-old chicken. Johnson, alongside young co-star Theo Clark Leber, sports extensive makeup, prosthetics, and weight loss for the role, directed by Benny Safdie with a cast including Rachel McAdams, Jeff Goldblum, and others. Set for a Christmas Day 2027 theatrical release, the family adventure captures whimsical moments like pizza slices and a giant lizard plush, drawing praise for Johnson's bold shift to dramatic roles.", "summary_zh": "他正在拍摄《Lizard Music》，这部真人与 CGI 结合的作品改编自丹尼尔·平克沃特 1976 年童书：男孩在深夜电视发现演奏异界音乐的蜥蜴，并结识鸡肉人及其 111 岁老母鸡。强森与年轻对手戏演员 Theo Clark Leber 同台，依赖大量化妆、假体与减重塑形；导演为本尼·萨夫迪，卡司还包括瑞秋·麦克亚当斯、杰夫·高布伦等。影片定档 2027 年圣诞节院线上映，花絮中披萨片与巨型蜥蜴玩偶尽显奇幻，外界称赞强森大胆转向戏剧角色。", "body_en": "Dwayne Johnson Transforms into 70-Year-Old Chicken Man for Lizard Music.\n\nDwayne Johnson stepped out on New York streets looking worlds away from his ripped action-hero self—gray hair, wrinkles, and a bucket hat making him truly unrecognizable as the eccentric Chicken Man.\n\nHe's filming Lizard Music, a live-action/CGI adaptation of Daniel Pinkwater’s 1976 children’s book about a boy who discovers lizards playing otherworldly music on late-night TV and befriends the Chicken Man and his 111-year-old chicken.\n\nJohnson, alongside young co-star Theo Clark Leber, sports extensive makeup, prosthetics, and weight loss for the role, directed by Benny Safdie with a cast including Rachel McAdams, Jeff Goldblum, and others. Set for a Christmas Day 2027 theatrical release, the family adventure captures whimsical moments like pizza slices and a giant lizard plush, drawing praise for Johnson's bold shift to dramatic roles.", "body_zh": "巨石强森变装 70 岁「鸡肉人」出演《Lizard Music》。\n\n巨石强森现身纽约街头：灰发、皱纹、渔夫帽，几乎认不出他就是古怪的「鸡肉人」。\n\n他正在拍摄《Lizard Music》，这部真人与 CGI 结合的作品改编自丹尼尔·平克沃特 1976 年童书：男孩在深夜电视发现演奏异界音乐的蜥蜴，并结识鸡肉人及其 111 岁老母鸡。\n\n强森与年轻对手戏演员 Theo Clark Leber 同台，依赖大量化妆、假体与减重塑形；导演为本尼·萨夫迪，卡司还包括瑞秋·麦克亚当斯、杰夫·高布伦等。影片定档 2027 年圣诞节院线上映，花絮中披萨片与巨型蜥蜴玩偶尽显奇幻，外界称赞强森大胆转向戏剧角色。", "url": "https://x.com/i/trending/2112352804241285515", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T09:06:08.000Z"}, {"id": "2112743486222905714", "domain": "娱乐", "title_en": "Skarsgård Brothers Shine at Wicker Premiere", "title_zh": "斯卡斯加德兄弟亮相《Wicker》首映", "hook_en": "Alexander Skarsgård turned heads with a black shirt framed by Olivia Colman's face, standing tall next to brother Bill in burgundy on the red carpet.", "hook_zh": "亚历山大·斯卡斯加德身着印有奥利维娅·科尔曼面孔的黑衬衫亮相，身旁弟弟比尔酒红造型形成鲜明对比。", "summary_en": "The Los Angeles premiere of romantic fantasy comedy Wicker on October 20 brought the Skarsgård brothers together, with Alexander in playful attire honoring co-star Olivia Colman and Bill offering sharp sibling contrast. Fans loved the shirt tribute and the brothers' entertaining dynamic, while Colman joined for photos and a lively Q&A with directors Alex Huston Fischer and Eleanor Wilson. The film adapts The Wicker Husband short story about a fisherwoman's woven spouse stirring village drama, hitting U.S. theaters October 23 with stars like Peter Dinklage and Elizabeth Debicki.", "summary_zh": "浪漫奇幻喜剧《Wicker》10 月 20 日洛杉矶首映，斯卡斯加德兄弟同台：亚历山大以趣味装扮向搭档奥利维娅·科尔曼致敬，比尔则形成鲜明反差。粉丝盛赞衬衫梗与兄弟互动；科尔曼一同拍照，并与导演 Alex Huston Fischer、Eleanor Wilson 参加问答。影片改编短篇《The Wicker Husband》，讲述渔妇编织出丈夫搅动村庄的故事，定于 10 月 23 日北美上映，卡司还包括彼得·丁拉基、伊丽莎白·德比茨基等。", "body_en": "Skarsgård Brothers Shine at Wicker Premiere.\n\nAlexander Skarsgård turned heads with a black shirt framed by Olivia Colman's face, standing tall next to brother Bill in burgundy on the red carpet.\n\nThe Los Angeles premiere of romantic fantasy comedy Wicker on October 20 brought the Skarsgård brothers together, with Alexander in playful attire honoring co-star Olivia Colman and Bill offering sharp sibling contrast. Fans loved the shirt tribute and the brothers' entertaining dynamic, while Colman joined for photos and a lively Q&A with directors Alex Huston Fischer and Eleanor Wilson.\n\nThe film adapts The Wicker Husband short story about a fisherwoman's woven spouse stirring village drama, hitting U.S. theaters October 23 with stars like Peter Dinklage and Elizabeth Debicki.", "body_zh": "斯卡斯加德兄弟亮相《Wicker》首映。\n\n亚历山大·斯卡斯加德身着印有奥利维娅·科尔曼面孔的黑衬衫亮相，身旁弟弟比尔酒红造型形成鲜明对比。\n\n浪漫奇幻喜剧《Wicker》10 月 20 日洛杉矶首映，斯卡斯加德兄弟同台：亚历山大以趣味装扮向搭档奥利维娅·科尔曼致敬，比尔则形成鲜明反差。\n\n粉丝盛赞衬衫梗与兄弟互动；科尔曼一同拍照，并与导演 Alex Huston Fischer、Eleanor Wilson 参加问答。影片改编短篇《The Wicker Husband》，讲述渔妇编织出丈夫搅动村庄的故事，定于 10 月 23 日北美上映，卡司还包括彼得·丁拉基、伊丽莎白·德比茨基等。", "url": "https://x.com/i/trending/2112743486222905714", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T08:16:30.000Z"}, {"id": "2112623564083876203", "domain": "娱乐", "title_en": "Hudson Williams Embraces New Role in 'Yaga' with Fan Support", "title_zh": "Hudson Williams 迎来《Yaga》新角色，粉丝力挺转型", "hook_en": "Hudson Williams felt a wave of relief when fans cheered his leap from steamy hockey romance to supernatural thriller. Their excitement for 'Yaga' showed his appeal goes beyond one hit role.", "hook_zh": "从火辣冰球恋到超自然惊悚，Hudson Williams 因粉丝为《Yaga》欢呼而松了口气——他们的热情证明其魅力不止一角。", "summary_en": "The 25-year-old Canadian actor, known for Shane Hollander in 'Heated Rivalry,' stars in dual roles as Henry Park and Logan in the upcoming Crave and AMC+ series 'Yaga,' premiering October 23. The show reimagines Slavic folklore with Baba Yaga in a modern mystery thriller featuring desire, ancient magic, and leads like Carrie-Anne Moss and Noah Reid. On set, Williams shared laughs with 'Heated Rivalry' nods, while opening up about fame's challenges like privacy invasions, yet crediting fans for keeping his work alive. Their warm responses highlight his growing, versatile draw.", "summary_zh": "这位 25 岁加拿大演员因《Heated Rivalry》中的 Shane Hollander 走红，即将在 Crave 与 AMC+ 剧集《Yaga》中分饰 Henry Park 与 Logan，10 月 23 日首播。剧集以现代神秘惊悚重塑斯拉夫传说中的芭芭雅嘎，交织欲望与古老魔法，主演还包括 Carrie-Anne Moss、Noah Reid。片场他与旧作梗互梗，也谈及成名后隐私被侵等问题，并感谢粉丝让作品持续发光；温暖反馈显示其跨类型号召力在扩大。", "body_en": "Hudson Williams Embraces New Role in 'Yaga' with Fan Support.\n\nHudson Williams felt a wave of relief when fans cheered his leap from steamy hockey romance to supernatural thriller. Their excitement for 'Yaga' showed his appeal goes beyond one hit role.\n\nThe 25-year-old Canadian actor, known for Shane Hollander in 'Heated Rivalry,' stars in dual roles as Henry Park and Logan in the upcoming Crave and AMC+ series 'Yaga,' premiering October 23. The show reimagines Slavic folklore with Baba Yaga in a modern mystery thriller featuring desire, ancient magic, and leads like Carrie-Anne Moss and Noah Reid.\n\nOn set, Williams shared laughs with 'Heated Rivalry' nods, while opening up about fame's challenges like privacy invasions, yet crediting fans for keeping his work alive. Their warm responses highlight his growing, versatile draw.", "body_zh": "Hudson Williams 迎来《Yaga》新角色，粉丝力挺转型。\n\n从火辣冰球恋到超自然惊悚，Hudson Williams 因粉丝为《Yaga》欢呼而松了口气——他们的热情证明其魅力不止一角。\n\n这位 25 岁加拿大演员因《Heated Rivalry》中的 Shane Hollander 走红，即将在 Crave 与 AMC+ 剧集《Yaga》中分饰 Henry Park 与 Logan，10 月 23 日首播。\n\n剧集以现代神秘惊悚重塑斯拉夫传说中的芭芭雅嘎，交织欲望与古老魔法，主演还包括 Carrie-Anne Moss、Noah Reid。片场他与旧作梗互梗，也谈及成名后隐私被侵等问题，并感谢粉丝让作品持续发光；温暖反馈显示其跨类型号召力在扩大。", "url": "https://x.com/i/trending/2112623564083876203", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T23:00:33.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "A detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more. The 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T20:43:03.000Z"}, {"id": "2112160143613874580", "domain": "科学", "title_en": "Trump Signs Order for NIH Women’s Health Division and Task Force", "title_zh": "特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组", "hook_en": "First Lady Melania Trump stood beside President Trump as he signed the executive order, calling it a transformative moment for women's health in America.", "hook_zh": "第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。", "summary_en": "On October 19, President Donald Trump signed an executive order establishing a new Women’s Health Division at the National Institutes of Health and a White House task force co-led by Chief of Staff Susie Wiles and HHS Secretary Robert F. Kennedy Jr. The initiative targets research gaps in conditions like osteoporosis, Alzheimer’s, heart disease, endometriosis, and maternal health, with the division to launch within 90 days. Melania Trump outlined five pillars for innovation, including AI-driven discoveries and affordable therapies, while Wiles shared how her breast cancer experience made early detection personal.", "summary_zh": "行政令设立 NIH 女性健康分部与白宫工作组，聚焦骨质疏松、阿尔茨海默病、心脏病、子宫内膜异位症与孕产妇健康等。", "body_en": "Trump Signs Order for NIH Women’s Health Division and Task Force.\n\nFirst Lady Melania Trump stood beside President Trump as he signed the executive order, calling it a transformative moment for women's health in America.\n\nOn October 19, President Donald Trump signed an executive order establishing a new Women’s Health Division at the National Institutes of Health and a White House task force co-led by Chief of Staff Susie Wiles and HHS Secretary Robert F. Kennedy Jr.\n\nThe initiative targets research gaps in conditions like osteoporosis, Alzheimer’s, heart disease, endometriosis, and maternal health, with the division to launch within 90 days. Melania Trump outlined five pillars for innovation, including AI-driven discoveries and affordable therapies, while Wiles shared how her breast cancer experience made early detection personal.", "body_zh": "特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组。\n\n第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。\n\n行政令设立 NIH 女性健康分部与白宫工作组，聚焦骨质疏松、阿尔茨海默病、心脏病、子宫内膜异位症与孕产妇健康等。\n\n第一夫人梅拉尼娅陪同总统签署面向女性健康的行政令。\n\n综合以上信息，特朗普签署行政令，设立 NIH 女性健康分部与白宫工作组一事持续引发关注。", "url": "https://x.com/i/trending/2112160143613874580", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T01:11:38.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "Reflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州沙漠模拟「轨道阳光」。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\nReflect Orbital 用地面灯具照亮约三英里范围，测试搜救用途；并预告将发射带镜子的卫星星座，向目标区域投送定向阳光。\n\n综合以上信息，Reflect Orbital 在加州沙漠模拟「轨道阳光」一事持续引发关注。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112640445633499411", "domain": "科学", "title_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals", "title_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI", "hook_en": "Imagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.", "hook_zh": "像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。", "summary_en": "The startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more. Co-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "summary_zh": "初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "body_en": "Electric Plant Launches Bombadil AI to Read Plant Electrical Signals.\n\nImagine slipping a tiny sensor into a plant and getting a real-time readout of its health, just like monitoring brainwaves. Electric Plant's new AI, Bombadil, makes that possible by decoding subtle electrical signals from living plants.\n\nThe startup pairs low-cost Bud sensors with Bombadil, a foundation model trained on over seven million hours of data from 125 plant species, to track stress, water needs, photosynthesis efficiency, and more.\n\nCo-founder Justin Mast says it could cut water use by 20 percent or more for growers by enabling precise irrigation based on individual plant signals rather than soil alone. Backed by an $11.2 million seed round, the team—from neuroscientists to AI experts—built it after years of recording signals in labs, forests, and orchards, with early enthusiasm for its potential in farming and climate tech.", "body_zh": "Electric Plant 推出 Bombadil：解读植物电信号的 AI。\n\n像监测脑电一样，把微型传感器接入植物即可实时读健康——Bombadil 解码活体植物微弱电信号。\n\n初创公司将低成本 Bud 传感器与在 125 种植物、逾 700 万小时数据上训练的基础模型 Bombadil 组合，追踪胁迫、需水、光合效率等。联合创始人 Justin Mast 称，按单株信号而非仅土壤精准灌溉，种植者用水或可降 20% 以上。\n\n种子轮 1120 万美元；团队含神经科学家与 AI 专家，经年在实验室、森林与果园记录信号，农业与气候科技前景获早期热捧。", "url": "https://x.com/i/trending/2112640445633499411", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-20T20:33:11.000Z"}, {"id": "2112660061256335405", "domain": "科学", "title_en": "Florida Poly Police Debut First U.S. eVTOL for Campus Patrols", "title_zh": "佛州理工警方启用美国校园首架 eVTOL 巡逻", "hook_en": "Imagine a compact flying machine zipping over a sunny campus, letting officers reach remote spots faster than ever. Florida Polytechnic University just made that real with their new electric aircraft named Astro.", "hook_zh": "紧凑电动飞行器掠过阳光校园，警员更快抵达偏远角落。佛罗里达理工大学用名为 Astro 的新电动飞行器把它变成现实。", "summary_en": "The Florida Polytechnic University Police Department introduced the Jetson ONE eVTOL, a single-seat electric flyer reaching 63 mph with 20 minutes of flight time, for surveillance, emergencies, and accessing hard-to-reach areas on the Lakeland campus. Police Chief Aaron Murray called it a proactive step into advanced air mobility, with plans to partner with other agencies once FAA approval comes through. The $150,000 vehicle doubles as an educational tool for the school's aerospace engineering students, amid mixed reactions from excitement over innovation to worries about sky-high surveillance.", "summary_zh": "佛罗里达理工大学警察局推出 Jetson ONE eVTOL：单座电动飞行器时速可达 63 英里、续航约 20 分钟，用于莱克兰校园监控、应急与抵达难达区域。警察局长 Aaron Murray 称迈向先进空中交通的主动一步，获 FAA 批准后拟与其他机构合作。造价约 15 万美元的载具亦作航空航天学生教具；反应既有对创新的兴奋，也有对「空中监控」的担忧。", "body_en": "Florida Poly Police Debut First U.S. eVTOL for Campus Patrols.\n\nImagine a compact flying machine zipping over a sunny campus, letting officers reach remote spots faster than ever. Florida Polytechnic University just made that real with their new electric aircraft named Astro.\n\nThe Florida Polytechnic University Police Department introduced the Jetson ONE eVTOL, a single-seat electric flyer reaching 63 mph with 20 minutes of flight time, for surveillance, emergencies, and accessing hard-to-reach areas on the Lakeland campus.\n\nPolice Chief Aaron Murray called it a proactive step into advanced air mobility, with plans to partner with other agencies once FAA approval comes through. The $150,000 vehicle doubles as an educational tool for the school's aerospace engineering students, amid mixed reactions from excitement over innovation to worries about sky-high surveillance.", "body_zh": "佛州理工警方启用美国校园首架 eVTOL 巡逻。\n\n紧凑电动飞行器掠过阳光校园，警员更快抵达偏远角落。佛罗里达理工大学用名为 Astro 的新电动飞行器把它变成现实。\n\n佛罗里达理工大学警察局推出 Jetson ONE eVTOL：单座电动飞行器时速可达 63 英里、续航约 20 分钟，用于莱克兰校园监控、应急与抵达难达区域。警察局长 Aaron Murray 称迈向先进空中交通的主动一步，获 FAA 批准后拟与其他机构合作。\n\n造价约 15 万美元的载具亦作航空航天学生教具；反应既有对创新的兴奋，也有对「空中监控」的担忧。", "url": "https://x.com/i/trending/2112660061256335405", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T03:00:44.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112414671194009776", "domain": "科学", "title_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome", "title_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶", "hook_en": "Thousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.", "hook_zh": "成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。", "summary_en": "Rocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome. This step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "summary_zh": "火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "body_en": "Rocket Lab Videos Automated Machine Building Neutron Rocket Dome.\n\nThousands of hair-thin carbon fibers whip into place at blistering speeds, forming the massive forward dome for Neutron's Stage 1 tank. It's a glimpse into the precision powering Rocket Lab's next big leap.\n\nRocket Lab released footage of its automated fiber placement machine at the Maryland facility laying down carbon strands up to 100 meters per minute on custom molds for the Neutron rocket's large composite forward dome.\n\nThis step follows last week's news of a 2027 first-launch target after fixing voids in a prior manual dome, with CEO Peter Beck confirming refined processes and a successful aft dome. Investors and fans praised the update for building excitement around production progress toward a reusable rocket carrying 13,000 kg to orbit, with upcoming tests ahead.", "body_zh": "火箭实验室晒自动铺丝机制作 Neutron 整流罩穹顶。\n\n成千上万根发丝般碳纤维高速铺就 Neutron 一级贮箱巨大前穹顶。\n\n火箭实验室公布马里兰工厂自动铺丝机画面：以最高约每分钟 100 米在定制模具上铺碳丝，制作 Neutron 大型复合材料前穹顶。此前手工穹顶空隙问题已修复，CEO 彼得·贝克确认工艺改进与后穹顶成功，首飞目标 2027 年。\n\n投资者与粉丝为可复用、运力约 1.3 万公斤入轨的火箭量产进展叫好，后续测试将至。", "url": "https://x.com/i/trending/2112414671194009776", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-20T05:28:17.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "Years of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal. Current pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T09:36:27.000Z"}, {"id": "2112623559793066330", "domain": "科学", "title_en": "College Student with Brain Tumor to Meet Trump at Rally", "title_zh": "脑瘤大学生将在集会会见特朗普，呼吁治疗可及", "hook_en": "Braelyn Hollensbe, a 19-year-old thriving in college after beating grim odds against a massive brain tumor, gets a special moment with President Trump tomorrow alongside her proud mom.", "hook_zh": "19 岁布蕾琳·霍伦斯贝战胜巨大脑瘤重返大学，将与母亲一同在明日集会上与特朗普会面。", "summary_en": "Diagnosed three years ago with aggressive glioblastoma, Braelyn underwent surgery at UCLA and now receives DCVax-L, a personalized vaccine made from her own tumor cells, in the UK since it's unavailable in the US. Her latest scans show no recurrence, yet her family pays out-of-pocket for travel and doses through 2029, aided by GoFundMe. At tomorrow's Clemson rally, Amanda plans to share details on care barriers and push for better access to promising US-developed treatments. Her story, highlighted in a recent commentary, spotlights calls to empower patients and doctors over regulators in desperate cases.", "summary_zh": "三年前确诊侵袭性胶质母细胞瘤后，布蕾琳在加州大学洛杉矶分校接受手术，目前在英国使用由自身肿瘤细胞制成的个性化疫苗 DCVax-L——该疗法在美国尚不可及。最新扫描未见复发，但家人须自费承担赴英治疗至 2029 年的旅行与剂量，并靠 GoFundMe 筹资。在克莱姆森集会上，母亲阿曼达计划讲述就医障碍，推动更好获得美国研发却难落地的疗法。其故事在近期评论中被聚焦，呼吁在危急病例中更多赋权患者与医生，而非仅仰赖监管。", "body_en": "College Student with Brain Tumor to Meet Trump at Rally.\n\nBraelyn Hollensbe, a 19-year-old thriving in college after beating grim odds against a massive brain tumor, gets a special moment with President Trump tomorrow alongside her proud mom.\n\nDiagnosed three years ago with aggressive glioblastoma, Braelyn underwent surgery at UCLA and now receives DCVax-L, a personalized vaccine made from her own tumor cells, in the UK since it's unavailable in the US. Her latest scans show no recurrence, yet her family pays out-of-pocket for travel and doses through 2029, aided by GoFundMe.\n\nAt tomorrow's Clemson rally, Amanda plans to share details on care barriers and push for better access to promising US-developed treatments. Her story, highlighted in a recent commentary, spotlights calls to empower patients and doctors over regulators in desperate cases.", "body_zh": "脑瘤大学生将在集会会见特朗普，呼吁治疗可及。\n\n19 岁布蕾琳·霍伦斯贝战胜巨大脑瘤重返大学，将与母亲一同在明日集会上与特朗普会面。\n\n三年前确诊侵袭性胶质母细胞瘤后，布蕾琳在加州大学洛杉矶分校接受手术，目前在英国使用由自身肿瘤细胞制成的个性化疫苗 DCVax-L——该疗法在美国尚不可及。最新扫描未见复发，但家人须自费承担赴英治疗至 2029 年的旅行与剂量，并靠 GoFundMe 筹资。\n\n在克莱姆森集会上，母亲阿曼达计划讲述就医障碍，推动更好获得美国研发却难落地的疗法。其故事在近期评论中被聚焦，呼吁在危急病例中更多赋权患者与医生，而非仅仰赖监管。", "url": "https://x.com/i/trending/2112623559793066330", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:46:13.000Z"}]};
